"""
utils/logger.py — Lightweight passive episode logger (per-step CSV).
All values stored as-is; the logger never computes or aggregates.
"""

import csv
import os


class EpisodeLogger:
    """Buffers per-step data for one episode and writes to CSV on save()."""

    FIELDS = [
        "step", "coverage", "U", "U_norm", "policy_type", "mode",
        "alpha", "F1", "F2", "collision_count",
    ]

    def __init__(self, method, run_label, log_dir="results/logs"):
        self.method = method
        self.run_label = run_label
        safe = method.lower().replace(" ", "_").replace("@", "_")
        self.out_dir = os.path.join(log_dir, safe)
        os.makedirs(self.out_dir, exist_ok=True)
        self.filepath = os.path.join(self.out_dir, f"run_{run_label}.csv")
        self.buffer = []

    def log_step(self, step, coverage, U=None, U_norm=None, policy_type=None,
                 mode=None, alpha=None, F1=None, F2=None, collisions=0):
        self.buffer.append({
            "step": step,
            "coverage": round(coverage, 4),
            "U": round(U, 4) if U is not None else None,
            "U_norm": round(U_norm, 6) if U_norm is not None else None,
            "policy_type": policy_type,
            "mode": mode,
            "alpha": round(alpha, 4) if alpha is not None else None,
            "F1": F1,
            "F2": F2,
            "collision_count": collisions,
        })

    def save(self):
        with open(self.filepath, "w", newline="") as f:
            writer = csv.DictWriter(f, fieldnames=self.FIELDS)
            writer.writeheader()
            writer.writerows(self.buffer)
        self.buffer = []


#====================================================================================================
# FILE   : estimators/angular.py
# AIM    : Independent angular-configuration model (transposes Chao-U richness onto bearings).
# DETAILS: bearing = atan2(c-oy, r-ox); independent config if > ANG_TOL_DEG=15 deg (circular) from existing centers; greedy clustering, CLUSTER_CAP=8; immutable perception path vs deterministic fusion re-clustering (spec B9).
#====================================================================================================

"""
estimators/angular.py — Independent angular configuration model (Project08).

A cell accumulates a bearing observation every time it lies inside an agent's
FOV window. Two observations are "independent configurations" when their
bearing directions are separated by more than ANG_TOL (default 15 deg),
measured circularly. Clustering is greedy:

  - PERCEPTION (arrival order, spec A5): for a new angle, compute the circular
    distance to every existing center; if the nearest center is within ANG_TOL
    -> assign to it (no new cluster), otherwise start a new cluster, bounded
    by CLUSTER_CAP per cell. This is order-dependent by design (clusters are
    built as measurements stream in).
  - FUSION (spec B9): the two agents' RAW angle lists are unioned and
    re-clustered from scratch in sorted order (deterministic, exact).

The decision signal transposes V4's Chao-U exactly (see estimators/richness):
  - "visit"       := per-cell configuration count,
  - F1            := known traversable cells with exactly 1 configuration,
  - F2            := known traversable cells with exactly 2 configurations,
  - cap           := total undetermined cells = known traversable cells with
                     <= 1 configuration (not yet localizable; a single bearing
                     is rank-deficient and cannot localize a 2-D position).
"""

import numpy as np

from config import ANG_TOL_DEG, CLUSTER_CAP

ANG_TOL = np.deg2rad(ANG_TOL_DEG)
TWO_PI = 2.0 * np.pi


def angular_distance(a, b):
    """Circular distance between two angles, in radians, in [0, pi]."""
    d = (a - b) % TWO_PI
    return d if d <= np.pi else TWO_PI - d


def add_angle_to_clusters(centers, angle, tol=ANG_TOL, cap=CLUSTER_CAP):
    """Add one angle to an existing cluster-center list (immutable).

    Returns (new_centers, cap_hit):
      new_centers : a NEW list (the input is never mutated);
      cap_hit     : True if the angle would have started a new cluster but the
                    cap is already full (the observation is then discarded
                    from the count — mirrored by the cluster_cap_hit_frac).
    """
    new_centers = list(centers)
    for c in new_centers:
        d = (angle - c) % TWO_PI
        if d > np.pi:
            d = TWO_PI - d
        if d <= tol:
            return new_centers, False
    if len(new_centers) >= cap:
        return new_centers, True
    new_centers.append(angle)
    return new_centers, False


def greedy_cluster_centers(angles, tol=ANG_TOL, cap=CLUSTER_CAP):
    """Cluster a sequence of angles from scratch (deterministic).

    Sort the angles, then apply the greedy nearest-center rule in sorted order.
    Returns the list of cluster centers (length <= cap).
    """
    centers = []
    for a in sorted(angles):
        matched = False
        for c in centers:
            d = (a - c) % TWO_PI
            if d > np.pi:
                d = TWO_PI - d
            if d <= tol:
                matched = True
                break
        if not matched and len(centers) < cap:
            centers.append(a)
    return centers


def merge_raw_angle_lists(a, b, tol=ANG_TOL, cap=CLUSTER_CAP):
    """Fusion of two RAW angle lists: union + re-cluster from scratch.

    Spec B9 ("union des listes d'angles par cellule + re-clustering"):
    the union of the two agents' raw bearings is re-clustered in sorted
    order. This is exact by construction and independent of arrival order.
    """
    a = list(a)
    b = list(b)
    if not b:
        return a
    if not a:
        return b
    return greedy_cluster_centers(a + b, tol=tol, cap=cap)


#====================================================================================================
# FILE   : estimators/richness.py
# AIM    : Richness/uncertainty estimators operating ONLY on the agent knowledge bundle {visit, known, obs} (leak-free).
# DETAILS: chao_u variants: original/cap/bias/bias_cap (default 'bias_cap' locked); jackknife_u; ace_u; u_norm; alpha_from_U (K=0.5); alpha_threshold_from_U.
#====================================================================================================

"""
estimators/richness.py — Richness estimators for adaptive exploration.

All estimators operate EXCLUSIVELY on the agent's knowledge bundle
{visit, known, obs} produced by env.get_local_info(). They never touch
the environment's global state directly (leak-free by construction).

Shared logic:
  U_norm = min(U / total_known, 1.0)
  alpha  = U_norm / (U_norm + K), K_DEFAULT = 0.5
"""

import numpy as np

# =============================================================================
# Frequency helpers
# =============================================================================

def _frequency_counts(visit, known, obs, max_count=10):
    """freq[i] = number of known traversable cells visited exactly i times."""
    tr = known & ~obs
    vc = visit[tr]
    freqs = np.zeros(max_count + 1, dtype=np.float64)
    for i in range(1, max_count + 1):
        freqs[i] = float(np.sum(vc == i))
    return freqs


def _traversable_known(known, obs):
    return known & ~obs


# =============================================================================
# Estimators — return U (estimated number of still-unseen cells)
# =============================================================================

def chao_u(visit, known, obs, total_unknown=None, variant="original"):
    """
    Chao-U with selectable formula/cap (used to fix the pure_local saturation).

    variant:
      "original" : U = F1^2/(2F2); if F2 == 0, U = F1. No cap.
      "cap"      : original U, then U = min(U, total_unknown).
      "bias"     : bias-corrected U = F1(F1-1)/(2(F2+1)); the "+1" handles
                   F2=0 natively (U = F1(F1-1)/2), floored at 1.
      "bias_cap" : bias-corrected U, then capped at total_unknown.

    All variants floor U at 1. total_unknown must be provided for cap variants.
    """
    freqs = _frequency_counts(visit, known, obs)
    F1 = freqs[1]
    F2 = freqs[2]
    if variant == "bias" or variant == "bias_cap":
        U = (F1 * (F1 - 1)) / (2.0 * (F2 + 1))
    else:
        if F2 > 0:
            U = (F1 ** 2) / (2.0 * F2)
        else:
            U = F1
    if variant == "cap" or variant == "bias_cap":
        U = min(U, float(max(total_unknown, 0)) if total_unknown is not None else U)
    return max(float(U), 1.0)


def chao_u_components(visit, known, obs):
    """Return (F1, F2) for trace/diagnostics (same counts as chao_u)."""
    freqs = _frequency_counts(visit, known, obs)
    return float(freqs[1]), float(freqs[2])


def jackknife_u(visit, known, obs):
    """Jackknife-U: U = F1 (singleton count). Floor at 1."""
    freqs = _frequency_counts(visit, known, obs)
    return max(float(freqs[1]), 1.0)


def ace_u(visit, known, obs, total_unknown):
    """
    Abundance-based Coverage Estimator.
    U_ACE = S_ACE - S_obs, then capped at min(U_ACE, total_unknown).
    The cap prevents C_ACE ~ 0 during swarm exploration from exploding
    U_ACE beyond the grid; uses the agent's own unknown count.
    """
    tr = _traversable_known(known, obs)
    vc = visit[tr]
    S_obs = float(np.sum(vc > 0))

    freqs = _frequency_counts(visit, known, obs, max_count=10)

    F1 = freqs[1]
    F2 = freqs[2]
    S_rare = float(np.sum(freqs[1:11]))
    N_rare = float(np.sum(np.arange(1, 11) * freqs[1:11]))

    if N_rare <= 1.0:
        return max(float(F1), 1.0)

    C_ACE = 1.0 - F1 / N_rare
    if C_ACE < 1e-10:
        return max(float(F1), 1.0)

    sum_i_im1 = float(np.sum(np.arange(1, 11) * np.arange(0, 10) * freqs[1:11]))
    gamma2 = (S_rare / C_ACE) * sum_i_im1 / (N_rare * (N_rare - 1.0)) - 1.0
    gamma2 = max(gamma2, 0.0)

    S_abund = float(np.sum(vc > 10))
    S_ACE = S_abund + S_rare / C_ACE + (F1 / C_ACE) * gamma2
    U = max(S_ACE - S_obs, 0.0)
    return max(min(U, float(max(total_unknown, 0))), 1.0)


def total_known(known, obs):
    return int(np.sum(_traversable_known(known, obs)))


# =============================================================================
# Normalisation + alpha
# =============================================================================

def u_norm(U, total_known):
    return min(float(U) / max(float(total_known), 1.0), 1.0)


def alpha_from_U(U, total_known, K=0.5):
    """U_norm / (U_norm + K), clipped to [0, 1]."""
    norm = u_norm(U, total_known)
    den = norm + K
    if den <= 1e-12:
        return 0.0, norm
    return float(np.clip(norm / den, 0.0, 1.0)), norm


def alpha_threshold_from_U(U, total_known, K=0.5, tau=0.1, U_max=1.0):
    """Threshold + linear decision strategy.

    alpha = 0                         if U_norm < tau   (pure exploit)
    alpha = (U_norm - tau)/(U_max - tau)               otherwise, clipped to [0,1].

    tau filters noisy low-richness states (drops exploration pressure once the
    local map looks "saturated"); late in an episode this degenerates the
    adaptive estimator into the myopic Greedy exploit, which wins at low FOV.
    K is accepted for signature parity with alpha_from_U (unused here).
    """
    norm = u_norm(U, total_known)
    if norm < tau:
        return 0.0, norm
    span = max(float(U_max) - float(tau), 1e-9)
    return float(np.clip((norm - tau) / span, 0.0, 1.0)), norm


def estimator_from_name(name):
    """Map estimator name -> callable (visit, known, obs[, total_unknown])."""
    return {
        "chao": chao_u,
        "jackknife": jackknife_u,
        "ace": ace_u,
    }[name]


