# FILE   : estimators/validation.py
# AIM    : Empirical Phase-1a validation: Gauss-Newton triangulation + Spearman correlations.
# DETAILS: gauss_newton_localize 12 iters tol 1e-9 init=observer centroid; noise sigma = QUALITY_SIGMA_BEARING_DEG = 1.0 deg; error in grid-cell units, +inf for non-localizable.
#====================================================================================================

"""
estimators/validation.py — Empirical validation of the localization model
(Phase 1a).

Purpose: confirm that (i) the bearing observations collected during an episode
actually localize cells (Gauss-Newton triangulation under angular noise), and
(ii) the decision/evaluation signals are valid proxies:
  - CRLB bound  (global oracle, env.global_bound_grid)  vs empirical error:
        positive Spearman correlation (bound grows with error);
  - local config count U (agent's fused view) vs empirical error:
        negative Spearman correlation (more configurations -> lower error).

The Gauss-Newton estimator inlines the exact geometric convention of env.py:
a cell at grid position (r, c) is observed from an agent at (or, oc) with true
bearing  atan2(c - oc, r - or). Noisy bearings are drawn N(0, sigma_deg).
"""

import numpy as np
from scipy.stats import spearmanr

from config import QUALITY_SIGMA_BEARING_DEG


def true_bearing(observer, cell):
    """Bearing from observer (or, oc) to cell (r, c), radians in (-pi, pi]."""
    or_, oc = observer
    r, c = cell
    return np.arctan2(c - oc, r - or_)


def gauss_newton_localize(observers, noisy_bearings, init=None, iters=12,
                          tol=1e-9):
    """Gauss-Newton bearing-only triangulation.

    observers      : list of (or, oc) true observer positions (grid cells).
    noisy_bearings : measured bearings (radians), same length.
    Returns (x, y) estimate in grid-cell coordinates, or (nan, nan) if the
    information matrix is rank deficient (< 2 independent directions).
    """
    obs = np.asarray(observers, dtype=np.float64)
    if obs.ndim != 2 or obs.shape[0] < 2:
        return (float("nan"), float("nan"))
    n = obs.shape[0]
    th = np.asarray(noisy_bearings, dtype=np.float64).reshape(n)

    if init is None:
        p = obs.mean(axis=0).copy()
    else:
        p = np.asarray(init, dtype=np.float64).copy().reshape(2)

    for _ in range(iters):
        dx = p[0] - obs[:, 0]
        dy = p[1] - obs[:, 1]
        d2 = dx * dx + dy * dy
        if np.any(d2 < 1e-12):
            return (float("nan"), float("nan"))  # observer on the target
        J = np.empty((n, 2))
        J[:, 0] = -dy / d2
        J[:, 1] = dx / d2
        residual = (np.arctan2(dy, dx) - th) % (2.0 * np.pi)
        residual = np.where(residual > np.pi, residual - 2.0 * np.pi, residual)

        H = J.T @ J
        det = H[0, 0] * H[1, 1] - H[0, 1] * H[1, 0]
        if det < 1e-12:
            return (float("nan"), float("nan"))  # rank deficient
        g = J.T @ residual
        step = np.linalg.solve(H, g)
        p = p - step
        if float(np.max(np.abs(step))) < tol:
            break
    return float(p[0]), float(p[1])


def empirical_errors(env, rng, sigma_deg=None, sample_cells=None):
    """Per-cell empirical localization error from the recorded observations.

    Uses env.global_raw_obs (must be enabled during the episode). For every
    traversable cell, triangulate from its TRUE observer positions + Gaussian
    bearing noise; unobservable cells get +inf error. Returns an (gs, gs)
    float grid (inf where not localizable) and the dict cell->error.
    """
    gs = env.grid_size
    if sigma_deg is None:
        sigma_deg = QUALITY_SIGMA_BEARING_DEG
    sigma = np.deg2rad(sigma_deg)

    errors = np.full((gs, gs), np.inf, dtype=np.float64)
    error_map = {}
    tr = ~env.obstacle_map
    cells = (np.argwhere(tr) if sample_cells is None else sample_cells)
    for r, c in cells:
        cell = int(r * gs + c)
        obs_list = env.global_raw_obs.get(cell)
        if not obs_list:
            continue
        th_true = np.array([true_bearing(o, (int(r), int(c)))
                            for o in obs_list])
        noise = rng.normal(0.0, sigma, size=th_true.size)
        x, y = gauss_newton_localize(obs_list, th_true + noise)
        if not np.isfinite(x):
            continue  # remains +inf (not localizable)
        err = np.hypot(x - float(r), y - float(c))
        errors[r, c] = err
        error_map[cell] = err
    return errors, error_map


def spearman(x, y):
    """(rho, p) Spearman rank correlation; (nan, 1.0) if degenerate."""
    x = np.asarray(x, dtype=np.float64).ravel()
    y = np.asarray(y, dtype=np.float64).ravel()
    if x.size < 3:
        return float("nan"), 1.0
    rho, p = spearmanr(x, y)
    return float(rho), float(p)


def cell_data(env, rng, include_undetermined=True, sigma_deg=None):
    """Per-cell (bound, u_local, u_global, error) arrays.

    include_undetermined=True  -> all traversable cells (unobserved get +inf);
    include_undetermined=False -> only cells with finite GN error (localizable).
    Returns (bound, u_local, u_global, error) numpy arrays, same cell order.
    """
    errors, _ = empirical_errors(env, rng, sigma_deg=sigma_deg)
    bound = env.global_bound_grid()
    u_local = env.get_config_count_grid(0).astype(np.float64)
    u_global = env.global_config_count_grid().astype(np.float64)
    tr = ~env.obstacle_map
    if not include_undetermined:
        tr = tr & np.isfinite(errors)
    idx = np.argwhere(tr)
    return (bound[idx[:, 0], idx[:, 1]],
            u_local[idx[:, 0], idx[:, 1]],
            u_global[idx[:, 0], idx[:, 1]],
            errors[idx[:, 0], idx[:, 1]])


def validate_phase1a(env, rng, include_undetermined=True):
    """Full Phase-1a validation on a finished episode.

    Returns a dict with, over the selected traversable cells:
      n_cells                  : number of cells tested,
      n_localizable            : cells with finite GN error,
      rho_bound_error          : Spearman(CRLB bound, empirical error),
      rho_U_local_error        : Spearman(local config count, error),
      rho_U_global_error       : Spearman(global config count, error),
      *_p                      : corresponding p-values.
    """
    bound, u_local, u_global, errors = cell_data(
        env, rng, include_undetermined=include_undetermined)
    if bound.size == 0:
        return {"n_cells": 0, "n_localizable": 0,
                "rho_bound_error": float("nan"),
                "rho_U_local_error": float("nan"),
                "rho_U_global_error": float("nan"),
                "rho_bound_error_p": 1.0,
                "rho_U_local_error_p": 1.0,
                "rho_U_global_error_p": 1.0}

    rho_be, p_be = spearman(bound, errors)
    rho_ule, p_ule = spearman(u_local, errors)
    rho_uge, p_uge = spearman(u_global, errors)
    return {
        "n_cells": int(bound.size),
        "n_localizable": int(np.sum(np.isfinite(errors))),
        "rho_bound_error": rho_be,
        "rho_U_local_error": rho_ule,
        "rho_U_global_error": rho_uge,
        "rho_bound_error_p": p_be,
        "rho_U_local_error_p": p_ule,
        "rho_U_global_error_p": p_uge,
    }


#====================================================================================================
# FILE   : env.py
# AIM    : The shared grid-world environment: agent movement, FOV perception, per-agent memory, limited-range fusion, global CRLB oracle.
# DETAILS: info_model spectrum pure_local <= comm_limited (production) <= fov_perfect. step(): collision -> one random winner. check_and_merge: proximity fusion (visit=max, seen/obs=union, angles=union re-clustered). CRLB J=sum w u u^T, w=1/(sigma^2 d^2); bound=sqrt((J00+J11)/(J00*J11-J01^2)) or +inf. Global oracle NEVER fed to policies. update_local_memory is the sensor hook every policy calls first.
#====================================================================================================

"""
env.py — Grid environment for UAV swarm coverage. V3 (comm_limited info model).

INFO MODEL
----------
comm_limited  (V3 default): limited-range communication with proximity-triggered
  (rendezvous) fusion. Each agent keeps a private memory:
  - agent_own_visit_count[agent_id]: counts only cells THIS agent visited.
  - local_visit_count[agent_id]    : what the agent "knows" — initialized to
    its own counts, updated by FUSION when agents meet within COMM_RANGE.
  - local_seen_mask[agent_id]      : cells ever seen inside its FOV (or a
    neighbor's FOV via fusion) — occupancy mask.
  - local_obstacle_map[agent_id]   : obstacles ever seen (FOV + fusion).
  Fusion is symmetric: both agents keep the combined knowledge (visit = MAX,
  seen/obstacle = union). No global visit_count / obstacle_map is ever fed to
  a policy. Collision resolution is handled by the environment from REAL agent
  positions (position-only channel), fully independent of COMM_RANGE/fusion.

pure_local  (V2 reference): zero communication — each agent perceives ONLY its
  own history. Same structure, no fusion ever fires.

fov_perfect (ablation): perfect knowledge of the whole grid (global obstacle
  map + global visit counts). Used as the upper bound of the spectrum.

The canonical spectrum: pure_local <= comm_limited <= fov_perfect.
"""

import math

import numpy as np

from estimators.angular import (ANG_TOL, CLUSTER_CAP,
                                add_angle_to_clusters, greedy_cluster_centers)


class GridEnv:
    """
    2-D grid world shared by all UAV agents.

    Action encoding: 0=up, 1=down, 2=left, 3=right, 4=stay

    ANGULAR OBSERVATION MODEL (Project08): every time a traversable cell lies
    inside an agent's FOV, the agent records the bearing (atan2) to that cell.
    Per (agent, cell) the bearings are greedily clustered into independent
    angular configurations (> ANG_TOL apart), capped at CLUSTER_CAP. The local
    configuration-count grid mirrors local_visit_count (decision signal);
    a GLOBAL oracle accumulator (metrics only, never fed to policies) records
    the bearing-only Fisher information per cell for the CRLB evaluation.
    """

    def __init__(self, grid_size=100, num_agents=6, obstacle_ratio=0.05,
                 seed=0, info_model="pure_local", p_miss=0.0, sigma_loc=0.0,
                 comm_range=None):
        self.grid_size = grid_size
        self.num_agents = num_agents
        self.obstacle_ratio = obstacle_ratio
        self.seed = seed
        self.info_model = info_model
        self.p_miss = p_miss
        self.sigma_loc = sigma_loc
        if info_model == "comm_limited" and comm_range is None:
            from config import COMM_RANGE
            comm_range = COMM_RANGE
        self.comm_range = comm_range

        self.rng = np.random.default_rng(seed)
        self._build_obstacle_map()

        # --- GLOBAL ground truth (metrics ONLY, never fed to policies) ---
        self.visit_count = np.zeros((grid_size, grid_size), dtype=np.int32)

        # --- PER-AGENT OWN MEMORY ---
        # Only incremented when the agent itself steps onto the cell.
        self.agent_own_visit_count = [
            np.zeros((grid_size, grid_size), dtype=np.int32)
            for _ in range(num_agents)
        ]
        # What the agent "knows": own visits, augmented by rendezvous fusion
        # (comm_limited). For pure_local it stays == own counts.
        self.local_visit_count = [
            np.zeros((grid_size, grid_size), dtype=np.int32)
            for _ in range(num_agents)
        ]
        # Cells ever seen inside FOV (and, for comm_limited, via fusion).
        self.local_seen_mask = [
            np.zeros((grid_size, grid_size), dtype=bool)
            for _ in range(num_agents)
        ]
        # Obstacles ever seen inside FOV (unknown cells are treated as free).
        self.local_obstacle_map = [
            np.zeros((grid_size, grid_size), dtype=bool)
            for _ in range(num_agents)
        ]

        # Number of symmetric pair-merges performed (comm_limited only).
        self.fusion_events_count = 0
        self.last_rendezvous_pairs = 0

        # --- ANGULAR MEASUREMENT MODEL (Project08) ---
        # Per (agent, cell):
        #   local_angle_clusters : independent angular configuration CENTERS
        #       (greedy nearest-center, > ANG_TOL, capped at CLUSTER_CAP).
        #   local_raw_angles : deduplicated SET of raw bearings per cell, kept
        #       ONLY for exact re-clustering at fusion time (spec B9: union of
        #       raw angle lists -> sorted greedy re-cluster). Sets bound the
        #       merge cost: a cell's distinct bearings <= #distinct observer
        #       positions in FOV range (~121 for FOV=5), and set union never
        #       self-multiplies shared lists.
        #   local_*     : own + fused (mirrors local_visit_count).
        # Config-count grids (int8) are maintained incrementally so policies
        # read O(1) per cell. Shared local raw sets are copy-on-write: every
        # perception replaces the set with a new one, so a partner keeps its
        # own reference after fusion.
        self.local_angle_clusters = [{} for _ in range(num_agents)]
        self.local_raw_angles = [{} for _ in range(num_agents)]
        self.local_measurement_count = [
            np.zeros((grid_size, grid_size), dtype=np.int8)
            for _ in range(num_agents)
        ]
        # local_dirty[i][j]: set of cells whose data for agent i may differ from
        # agent j's since their last merge. Perception re-adds observed cells;
        # a merge (i,j) only visits dirty[i][j] U dirty[j][i] and then clears
        # both, propagating the merged cells to the other partners' dirty sets.
        # This keeps fusion cost proportional to CHANGE, not map size (the
        # whole-map iteration of V4-style merges explodes once agents travel
        # together: O(steps x map_size)).
        self.local_dirty = [
            [set() for _ in range(num_agents)] for _ in range(num_agents)
        ]

        # --- ANGULAR ORACLE (metrics ONLY, never fed to policies) ---
        # GLOBAL observation record: all agents' bearings, clustered globally.
        # global_info[cells, (0,1,2)] = accumulated bearing-only Fisher
        # information J00, J01, J11 per cell -> CRLB bound = sqrt(trace(J^-1)).
        # global_obs_count = per-cell count of observations (vectorized).
        self.global_angle_clusters = {}
        self.global_info = np.zeros((grid_size, grid_size, 3),
                                    dtype=np.float64)
        self.global_obs_count = np.zeros((grid_size, grid_size), dtype=np.int32)
        self.global_observation_count = 0
        self.global_cap_hit_count = 0
        # Optional raw recording (Phase 1a validation only): when enabled, the
        # TRUE observer positions behind each global observation are stored per
        # cell so a Gauss-Newton estimator can be run against noisy bearings.
        self.record_global_raw = False
        self.global_raw_obs = {}

        # Frontier BFS exhaustion cache (per-agent). When a policy's BFS
        # exhausts (no locally-unvisited cell reachable), the reachable
        # component can only shrink while the unvisited/obstacle knowledge is
        # unchanged, so the "no reachable target" result stays valid. The
        # masks are snapshots used to invalidate the cache. Behavior-identical.
        self.explore_exhausted = [False] * num_agents
        self.explore_exhausted_unvisited = [None] * num_agents
        self.explore_exhausted_obs = [None] * num_agents

        # --- Noise bookkeeping ---
        self.noise_rngs = [
            np.random.default_rng(seed + 1000 + i) for i in range(num_agents)
        ]
        self.loc_error_sum = 0.0
        self.loc_error_count = 0

        self.traversable = int(np.sum(~self.obstacle_map))
        self._place_agents()
        self.last_collision_count = 0
        self.sigma_bearing_ref = None  # lazy-loaded from config
        self.quality_threshold = None

    # ------------------------------------------------------------------
    # Setup
    # ------------------------------------------------------------------

    def _build_obstacle_map(self):
        """Random obstacles. Outer edge ring left free for spawn safety."""
        total = self.grid_size * self.grid_size
        inner = [(r, c) for r in range(1, self.grid_size - 1)
                 for c in range(1, self.grid_size - 1)]
        n_obs = int(total * self.obstacle_ratio)
        flat = np.zeros(total, dtype=bool)
        cand = self.rng.choice(len(inner), size=n_obs, replace=False)
        for idx in cand:
            r, c = inner[idx]
            flat[r * self.grid_size + c] = True
        self.obstacle_map = flat.reshape(self.grid_size, self.grid_size)

    def _place_agents(self):
        free = list(zip(*np.where(~self.obstacle_map)))
        replace_flag = len(free) < self.num_agents
        chosen = self.rng.choice(len(free), size=self.num_agents,
                                 replace=replace_flag)
        self.agent_positions = [list(free[i]) for i in chosen]
        for aid, (r, c) in enumerate(self.agent_positions):
            self.visit_count[r, c] += 1
            self.agent_own_visit_count[aid][r, c] += 1
            self.local_visit_count[aid][r, c] += 1

    # ------------------------------------------------------------------
    # Step
    # ------------------------------------------------------------------

    DELTAS = [(-1, 0), (1, 0), (0, -1), (0, 1), (0, 0)]

    def step(self, actions):
        """Move each agent. No stacking: contested cells keep one random
        winner, losers stay in place."""
        intended = []
        for agent_id, action in enumerate(actions):
            dr, dc = self.DELTAS[action]
            r, c = self.agent_positions[agent_id]
            nr, nc = r + dr, c + dc
            if (0 <= nr < self.grid_size and 0 <= nc < self.grid_size
                    and not self.obstacle_map[nr, nc]):
                intended.append((nr, nc))
            else:
                intended.append((r, c))

        from collections import defaultdict
        claimants = defaultdict(list)
        for agent_id, cell in enumerate(intended):
            claimants[cell].append(agent_id)

        self.last_collision_count = 0
        for cell, agents in claimants.items():
            if len(agents) > 1:
                self.last_collision_count += len(agents) - 1
                winner = int(self.rng.choice(agents))
                for loser in agents:
                    if loser != winner:
                        intended[loser] = self.agent_positions[loser][:]

        for agent_id in range(self.num_agents):
            nr, nc = intended[agent_id]
            self.agent_positions[agent_id] = [nr, nc]
            self.visit_count[nr, nc] += 1
            self.agent_own_visit_count[agent_id][nr, nc] += 1
            self.local_visit_count[agent_id][nr, nc] += 1

        return [pos[:] for pos in self.agent_positions]

    # ------------------------------------------------------------------
    # Communication (comm_limited): proximity-triggered fusion
    # ------------------------------------------------------------------

    def distance(self, i, j):
        """Euclidean distance between agents i and j (units = grid cells)."""
        return float(np.linalg.norm(
            np.asarray(self.agent_positions[i], dtype=float)
            - np.asarray(self.agent_positions[j], dtype=float)))

    def _within_comm_range(self, i, j):
        if self.comm_range is None:
            return False
        return self.distance(i, j) <= float(self.comm_range)

    def check_and_merge(self, agent_id_list=None):
        """Check all pairs of agents within COMM_RANGE and fuse their maps.
        Called ONCE per decision step, BEFORE FOV perception (§5.3 order).
        No-op for info models other than comm_limited."""
        if self.info_model != "comm_limited":
            return 0
        import itertools
        if agent_id_list is None:
            agent_id_list = list(range(self.num_agents))
        n_fusions = 0
        for i, j in itertools.combinations(agent_id_list, 2):
            if self._within_comm_range(i, j):
                self.merge_maps(i, j)
                n_fusions += 1
        self.last_rendezvous_pairs = n_fusions
        return n_fusions

    def merge_maps(self, i, j):
        """
        Symmetric merge: both agents leave with the COMBINED knowledge.
        - Visits  : element-wise MAX (never a sum, to avoid inflating F1/F2).
        - Seen    : boolean union.
        - Obstacles: boolean union (occupancy is shared geometry).
        - Angles  : union of independent configuration clusters per cell
          (re-clustered greedily; exact because centers are fixed reps).
        The merge is idempotent per pair; the counter counts pair-merges with
        new information. If neither agent changed anything since their last
        merge (dirty sets empty), the whole merge is a no-op.
        """
        if self.info_model == "comm_limited":
            if not self.local_dirty[i][j] and not self.local_dirty[j][i]:
                return
        merged_visit = np.maximum(self.local_visit_count[i],
                                  self.local_visit_count[j])
        merged_seen = self.local_seen_mask[i] | self.local_seen_mask[j]
        merged_obs = self.local_obstacle_map[i] | self.local_obstacle_map[j]

        self.local_visit_count[i] = merged_visit.copy()
        self.local_visit_count[j] = merged_visit.copy()
        self.local_seen_mask[i] = merged_seen
        self.local_seen_mask[j] = merged_seen.copy()
        self.local_obstacle_map[i] = merged_obs
        self.local_obstacle_map[j] = merged_obs.copy()

        self._merge_angle_maps(i, j)

        self.fusion_events_count += 1

    def _merge_angle_maps(self, i, j):
        """Union of the two agents' local configuration clusters (comm_limited).

        ONLY the cells in dirty[i][j] U dirty[j][i] are visited (the cells
        that may differ since the pair's last merge) — spec B9 "union des
        listes d'angles par cellule + re-clustering" applied exactly on those.
        For each such cell, merge the DEDUPLICATED raw angle sets and
        re-cluster from scratch in sorted order; both agents receive the SAME
        new raw set and center list. The merged cells are propagated to the
        other partners' dirty sets so multi-hop fusion stays exact.
        """
        di = self.local_dirty[i]
        dj = self.local_dirty[j]
        to_merge = di[j] | dj[i]
        if not to_merge:
            return

        ci = self.local_angle_clusters[i]
        cj = self.local_angle_clusters[j]
        ri = self.local_raw_angles[i]
        rj = self.local_raw_angles[j]
        count_i = self.local_measurement_count[i]
        count_j = self.local_measurement_count[j]
        gs = self.grid_size
        for cell in to_merge:
            ri_c = ri.get(cell)
            rj_c = rj.get(cell)
            if ri_c is None:
                # i has no data for this cell: adopt j's exactly (shared refs).
                ri[cell] = rj_c
                ci[cell] = cj[cell]
            elif rj_c is None:
                rj[cell] = ri_c
                cj[cell] = ci[cell]
            elif ri_c is rj_c:
                continue  # identical shared set -> nothing new to fuse
            elif ri_c <= rj_c:
                # union == rj_c -> exact re-cluster is j's current clustering
                ri[cell] = rj_c
                ci[cell] = cj[cell]
            elif rj_c <= ri_c:
                rj[cell] = ri_c
                cj[cell] = ci[cell]
            else:
                merged_raw = ri_c | rj_c
                merged_centers = greedy_cluster_centers(merged_raw)
                ri[cell] = merged_raw
                rj[cell] = merged_raw
                ci[cell] = merged_centers
                cj[cell] = merged_centers
            n = len(ci[cell])
            r, c = divmod(cell, gs)
            count_i[r, c] = n
            count_j[r, c] = n

        di[j].clear()
        dj[i].clear()
        for k in range(self.num_agents):
            if k == i or k == j:
                continue
            di[k].update(to_merge)
            dj[k].update(to_merge)

    # ------------------------------------------------------------------
    # FOV / memory
    # ------------------------------------------------------------------

    def get_fov_mask(self, r, c, fov_radius):
        """Square FOV window centred at (r, c), clamped to grid bounds."""
        gs = self.grid_size
        mask = np.zeros((gs, gs), dtype=bool)
        r0 = max(0, r - fov_radius)
        r1 = min(gs, r + fov_radius + 1)
        c0 = max(0, c - fov_radius)
        c1 = min(gs, c + fov_radius + 1)
        mask[r0:r1, c0:c1] = True
        return mask

    def update_local_memory(self, agent_id, fov_radius):
        """
        Merge visible cells into the agent's local memory.
        pure_local: only marks seen + obstacles (NEVER copies visit counts).
        fov_perfect: full knowledge (ablation).
        Every visible traversable cell also records a bearing observation
        (angular model). For fov_perfect, observations cover the whole grid.
        """
        if self.info_model == "fov_perfect":
            self.local_seen_mask[agent_id][:] = ~self.obstacle_map
            self.local_obstacle_map[agent_id][:] = self.obstacle_map
            self._record_fov_observations(agent_id, fov_radius, whole_grid=True)
            return

        x_obs, y_obs = self._observed_position(agent_id)
        fov = self.get_fov_mask(x_obs, y_obs, fov_radius)

        if self.p_miss > 0:
            rng = self.noise_rngs[agent_id]
            noise = rng.random(fov.shape) > self.p_miss
            fov = fov & noise

        self.local_seen_mask[agent_id][fov] = True
        self.local_obstacle_map[agent_id][fov] = self.obstacle_map[fov]
        self._record_fov_observations(agent_id, fov_radius, fov=fov,
                                      obs_pos=(x_obs, y_obs))

    def _record_fov_observations(self, agent_id, fov_radius, fov=None,
                                 whole_grid=False, obs_pos=None):
        """Record a bearing to every visible traversable cell (angular model).

        Local: per (agent, cell) independent angular configurations (greedy,
        > ANG_TOL, capped at CLUSTER_CAP). Own and local dicts/counts are
        updated separately (local may already contain fused clusters). The
        LOCAL bearing is measured from the observed position `obs_pos` (true
        position when None — identical in Phase 1).
        Global (metrics only): accumulates the bearing-only Fisher information
        per cell from the agent's TRUE position (oracle geometry) and the
        globally clustered configuration set. cap_hit is counted on the LOCAL
        decision signal (mirrors alpha_sat_frac).
        """
        if whole_grid:
            fov = np.ones(self.obstacle_map.shape, dtype=bool)
        elif fov is None:
            fov = self.get_fov_mask(*self.agent_positions[agent_id], fov_radius)
        mask = fov & ~self.obstacle_map
        rows, cols = np.nonzero(mask)
        n = int(rows.size)
        if n == 0:
            return

        if self.sigma_bearing_ref is None:
            from config import QUALITY_SIGMA_BEARING_DEG
            self.sigma_bearing_ref = math.radians(QUALITY_SIGMA_BEARING_DEG)

        # --- Oracle Fisher accumulation (true geometry, metrics only) ---
        r_true, c_true = self.agent_positions[agent_id]
        dy = rows - r_true
        dx = cols - c_true
        d2 = dy * dy + dx * dx
        keep = d2 > 0  # the agent never takes a bearing to its own cell
        rows, cols, dy, dx, d2 = (rows[keep], cols[keep],
                                  dy[keep], dx[keep], d2[keep])
        n = int(rows.size)
        if n == 0:
            return
        d = np.sqrt(d2)
        ux = -dy / d
        uy = dx / d
        w = 1.0 / (self.sigma_bearing_ref ** 2 * d2)
        info = self.global_info
        info[rows, cols, 0] += w * ux * ux
        info[rows, cols, 1] += w * ux * uy
        info[rows, cols, 2] += w * uy * uy

        # --- Per-cell local clustering (decision signal) ---
        if obs_pos is None:
            obs_pos = tuple(self.agent_positions[agent_id])
        ox, oy = obs_pos
        loc_centers = self.local_angle_clusters[agent_id]
        loc_raw = self.local_raw_angles[agent_id]
        gcl = self.global_angle_clusters
        loc_cnt = self.local_measurement_count[agent_id]
        gs = self.grid_size

        cap_hits = 0
        for r, c in zip(rows, cols):
            cell = int(r * gs + c)
            angle = math.atan2(c - oy, r - ox)

            # local record: raw SET (dedup, copy-on-write) + incremental
            # centers. cap_hit is counted on this LOCAL decision signal.
            lraw = loc_raw.get(cell)
            loc_raw[cell] = (lraw | {angle} if lraw is not None else {angle})
            newc_loc, hit = add_angle_to_clusters(loc_centers.get(cell, ()),
                                                  angle)
            loc_centers[cell] = newc_loc
            loc_cnt[r, c] = len(newc_loc)

            # global oracle: incremental centers only (no fusion at global level)
            newc_gl, _ = add_angle_to_clusters(gcl.get(cell, ()), angle)
            gcl[cell] = newc_gl
            cap_hits += int(hit)

        self.global_obs_count[rows, cols] += 1
        self.global_observation_count += n
        self.global_cap_hit_count += cap_hits

        if self.record_global_raw:
            gro = self.global_raw_obs
            for r, c, in zip(rows, cols):
                cell = int(r * gs + c)
                lst = gro.get(cell)
                if lst is None:
                    gro[cell] = [(ox, oy)]
                else:
                    lst.append((ox, oy))

        if self.info_model == "comm_limited":
            obs_cells = set((rows * gs + cols).tolist())
            di = self.local_dirty[agent_id]
            for j in range(self.num_agents):
                if j != agent_id:
                    di[j].update(obs_cells)

    def _observed_position(self, agent_id):
        """True position possibly corrupted by localisation noise."""
        r, c = self.agent_positions[agent_id]
        if self.sigma_loc <= 0:
            return int(r), int(c)
        rng = self.noise_rngs[agent_id]
        x_f = r + rng.normal(0, self.sigma_loc)
        y_f = c + rng.normal(0, self.sigma_loc)
        self.loc_error_sum += (x_f - r) ** 2 + (y_f - c) ** 2
        self.loc_error_count += 1
        return int(round(x_f)), int(round(y_f))

    def get_rmse_2d(self):
        if self.loc_error_count == 0:
            return 0.0
        return np.sqrt(self.loc_error_sum / self.loc_error_count)

    # ------------------------------------------------------------------
    # Knowledge interface (single access point for policies)
    # ------------------------------------------------------------------

    def get_visit_knowledge(self, agent_id):
        """Visit counts the agent may legitimately use."""
        if self.info_model == "fov_perfect":
            return self.visit_count
        if self.info_model == "comm_limited":
            return self.local_visit_count[agent_id]
        return self.agent_own_visit_count[agent_id]

    def get_known_mask(self, agent_id):
        """Cells the agent knows about (traversable-candidate set)."""
        if self.info_model == "fov_perfect":
            return ~self.obstacle_map
        return self.local_seen_mask[agent_id]

    def get_obstacle_knowledge(self, agent_id):
        """Obstacles the agent knows about."""
        if self.info_model == "fov_perfect":
            return self.obstacle_map
        return self.local_obstacle_map[agent_id]

    def get_total_unknown(self, agent_id):
        """Number of cells the agent believes are still to be covered.
        Used to cap ACE-U. Always expressed in the agent's frame."""
        if self.info_model == "fov_perfect":
            return int(np.sum((self.visit_count == 0) & ~self.obstacle_map))
        known = self.local_seen_mask[agent_id]
        obs = self.local_obstacle_map[agent_id]
        own = self.get_visit_knowledge(agent_id)
        traversable_known = known & ~obs
        return int(np.sum(traversable_known & (own == 0)))

    def get_local_info(self, agent_id):
        """Convenience bundle used by all estimators/policies."""
        return {
            "visit": self.get_visit_knowledge(agent_id),
            "known": self.get_known_mask(agent_id),
            "obs": self.get_obstacle_knowledge(agent_id),
        }

    def get_local_unvisited_mask(self, agent_id):
        """Targets for frontier exploration: known traversable cells the
        agent has not itself visited."""
        info = self.get_local_info(agent_id)
        return info["known"] & ~info["obs"] & (info["visit"] == 0)

    # ------------------------------------------------------------------
    # Angular knowledge interface (single access point for policies)
    # ------------------------------------------------------------------

    def get_config_count_grid(self, agent_id):
        """Per-cell local configuration count (int8 grid). This is the angular
        analog of local_visit_count and is the `visit` input of the transposed
        Chao-U richness signal. For fov_perfect (ablation), global counts."""
        if self.info_model == "fov_perfect":
            out = np.zeros((self.grid_size, self.grid_size), dtype=np.int8)
            for cell, centers in self.global_angle_clusters.items():
                r, c = divmod(cell, self.grid_size)
                out[r, c] = len(centers)
            return out
        return self.local_measurement_count[agent_id]

    def global_config_count_grid(self):
        """Per-cell global configuration count (all agents, true geometry).
        Used ONLY for validation diagnostics (Phase 1a), never by policies."""
        out = np.zeros((self.grid_size, self.grid_size), dtype=np.int8)
        for cell, centers in self.global_angle_clusters.items():
            r, c = divmod(cell, self.grid_size)
            out[r, c] = len(centers)
        return out

    def get_total_undetermined(self, agent_id):
        """Number of cells the agent believes are still unlocalized: KNOWN
        traversable cells with fewer than 2 independent angular configurations
        (a single bearing is rank-deficient / not localizable). This is the
        angular analog of get_total_unknown in V4 and caps the transposed
        Chao-U. Cells never seen are not counted (initial pool is 0, so the
        signal starts flat exactly like V4's Frontier+Richness)."""
        if self.info_model == "fov_perfect":
            count = self.get_config_count_grid(agent_id)
            return int(np.sum((count <= 1) & ~self.obstacle_map))
        count = self.local_measurement_count[agent_id]
        known = self.local_seen_mask[agent_id]
        obs = self.local_obstacle_map[agent_id]
        return int(np.sum(known & ~obs & (count <= 1)))

    # ------------------------------------------------------------------
    # Oracle CRLB (metrics ONLY, never fed to policies)
    # ------------------------------------------------------------------

    def global_bound_grid(self):
        """Per-cell bearing-only Cramer-Rao bound sqrt(trace(J^-1)) in grid
        cells, from the TRUE observation geometry. Cells with < 2 independent
        directions (rank-deficient J) or never observed get +inf."""
        J00 = self.global_info[..., 0]
        J01 = self.global_info[..., 1]
        J11 = self.global_info[..., 2]
        det = J00 * J11 - J01 * J01
        trace = J00 + J11
        bound = np.full_like(det, np.inf)
        ok = det > 1e-12
        bound[ok] = np.sqrt(trace[ok] / det[ok])
        return bound

    def global_undetermined_fraction(self):
        """Fraction of traversable cells with 0 global configurations
        (never observed), i.e. still unexplored/unlocalized space."""
        tr = ~self.obstacle_map
        if not self.traversable:
            return 0.0
        return float(np.sum((self.global_obs_count == 0) & tr)) / \
            self.traversable

    def cluster_cap_hit_frac(self):
        """Fraction of traversable observations blocked by the CLUSTER_CAP on
        the LOCAL decision signal (mirrors alpha_sat_frac). None if no
        observations yet."""
        if self.global_observation_count == 0:
            return None
        return float(self.global_cap_hit_count) / self.global_observation_count

    def quality_well_localized(self, threshold=None):
        """quality(t) = fraction of traversable cells whose CRLB bound
        <= threshold (grid cells). threshold defaults to config."""
        if threshold is None:
            if self.quality_threshold is None:
                from config import QUALITY_THRESHOLD
                self.quality_threshold = QUALITY_THRESHOLD
            threshold = self.quality_threshold
        bound = self.global_bound_grid()
        tr = ~self.obstacle_map
        if not self.traversable:
            return 0.0
        return float(np.sum((bound <= threshold) & tr)) / self.traversable

    # ------------------------------------------------------------------
    # Coverage helpers (metrics use GLOBAL truth)
    # ------------------------------------------------------------------

    def global_coverage(self):
        visited = int(np.sum((self.visit_count > 0) & ~self.obstacle_map))
        return 100.0 * visited / self.traversable if self.traversable else 0.0

    def local_coverage(self, agent_id):
        """Fraction of the agent's known traversable cells it has visited."""
        info = self.get_local_info(agent_id)
        tr = info["known"] & ~info["obs"]
        total = int(np.sum(tr))
        if total == 0:
            return 0.0
        visited = int(np.sum((info["visit"][tr] > 0)))
        return 100.0 * visited / total

    def reset(self):
        self.visit_count[:] = 0
        for i in range(self.num_agents):
            self.agent_own_visit_count[i][:] = 0
            self.local_visit_count[i][:] = 0
            self.local_seen_mask[i][:] = False
            self.local_obstacle_map[i][:] = False
        self.fusion_events_count = 0
        self.last_rendezvous_pairs = 0
        self.explore_exhausted = [False] * self.num_agents
        self.explore_exhausted_unvisited = [None] * self.num_agents
        self.explore_exhausted_obs = [None] * self.num_agents
        self.loc_error_sum = 0.0
        self.loc_error_count = 0
        for i in range(self.num_agents):
            self.local_angle_clusters[i].clear()
            self.local_raw_angles[i].clear()
            self.local_measurement_count[i][:] = 0
            for j in range(self.num_agents):
                self.local_dirty[i][j].clear()
        self.global_angle_clusters.clear()
        self.global_info[:] = 0.0
        self.global_obs_count[:] = 0
        self.global_observation_count = 0
        self.global_cap_hit_count = 0
        self.global_raw_obs.clear()
        self._place_agents()


class NoisyGridEnv(GridEnv):
    """Alias kept for backward compatibility with run scripts."""


#====================================================================================================
# FILE   : metrics.py
# AIM    : Global ground-truth coverage metrics (measurements, never policy inputs).
# DETAILS: coverage_percent, steps_to_threshold, overlap_ratio, unseen_estimator (bounded Chao F1^2/(2F2)), mean_nearest_neighbor_distance.
#====================================================================================================

"""
metrics.py — Global coverage metrics (GLOBAL ground truth only; these are
measurements for the report, never inputs to any policy).
"""

import numpy as np


def coverage_percent(env):
    visited = int(np.sum((env.visit_count > 0) & ~env.obstacle_map))
    return 100.0 * visited / env.traversable if env.traversable else 0.0


def steps_to_threshold(coverage_history, threshold=90.0):
    """First 1-based step index where coverage reached threshold; None if never."""
    for step, cov in enumerate(coverage_history, start=1):
        if cov >= threshold:
            return step
    return None


def overlap_ratio(env):
    """Fraction of total visits that are redundant (revisits)."""
    vc = env.visit_count[~env.obstacle_map]
    total = int(vc.sum())
    if total == 0:
        return 0.0
    unique = int(np.sum(vc > 0))
    return (total - unique) / total


def unseen_estimator(env):
    """Bounded global Chao-style estimate of remaining unseen cells (diagnostic)."""
    vc = env.visit_count[~env.obstacle_map]
    F1 = int(np.sum(vc == 1))
    F2 = int(np.sum(vc == 2))
    actual_unseen = int(np.sum(vc == 0))
    U = float(F1) if F2 == 0 else (F1 ** 2) / (2.0 * F2)
    return min(U, float(actual_unseen))


def mean_nearest_neighbor_distance(agent_positions):
    pos = np.array(agent_positions).astype(float)
    if len(pos) <= 1:
        return 0.0
    dists = np.sqrt(np.sum((pos[:, None, :] - pos[None, :, :]) ** 2, axis=-1))
    np.fill_diagonal(dists, np.inf)
    return float(np.mean(np.min(dists, axis=1)))


#====================================================================================================
# FILE   : policies/_common.py
# AIM    : Shared leak-free movement/selection helpers for ALL policies.
# DETAILS: bounded_bfs: canonical frame, horizon 8, paths through unknown+known-unvisited free, never through visited, returns (D, curdir), D=-1 beyond horizon. box_sum (integral image). explore_action (BFS to nearest locally-unvisited) + exhaustion cache; exploit_action (least own-visit known neighbor).
#====================================================================================================

"""
policies/_common.py — Shared low-level helpers used by all policies.

These helpers are LEAK-FREE: they only use env.local_* / knowledge
interface. Unknown cells (not marked as obstacles) are treated as free.
"""

import numpy as np


def valid_neighbors_local(env, agent_id, r, c, include_stay=False):
    """
    Valid moves using the agent's LOCAL obstacle memory.
    Unknown cells are considered free unless marked obstacle.
    Returns list of (action, nr, nc).
    """
    obs = env.get_obstacle_knowledge(agent_id)
    gs = env.grid_size
    moves = [
        (0, -1, 0),   # up
        (1, 1, 0),    # down
        (2, 0, -1),   # left
        (3, 0, 1),    # right
    ]
    if include_stay:
        moves.append((4, 0, 0))

    out = []
    for action, dr, dc in moves:
        nr, nc = r + dr, c + dc
        if 0 <= nr < gs and 0 <= nc < gs and not obs[nr, nc]:
            out.append((action, nr, nc))
    return out


def explore_action(env, agent_id, rng):
    """
    BFS towards the nearest locally-unvisited traversable cell.
    Fallback: random valid move (unknown cells are walkable).
    Returns (action, mode).

    Exhaustion cache: if a previous BFS exhausted (no reachable target) and
    neither the unvisited mask nor the obstacle knowledge changed, the
    component can only have shrunk, so the result is still "no reachable
    target" -> reuse the cached fallback (behavior-identical, rng stream
    unchanged because the fallback consumes rng exactly as the BFS path does).
    """
    r, c = env.agent_positions[agent_id]
    unvisited = env.get_local_unvisited_mask(agent_id)
    obs = env.get_obstacle_knowledge(agent_id)

    if env.explore_exhausted[agent_id]:
        cached_u = env.explore_exhausted_unvisited[agent_id]
        cached_o = env.explore_exhausted_obs[agent_id]
        if (cached_u is not None and cached_o is not None
                and np.array_equal(cached_u, unvisited)
                and np.array_equal(cached_o, obs)):
            neigh = valid_neighbors_local(env, agent_id, r, c, include_stay=True)
            if neigh:
                return int(rng.choice([a for a, _, _ in neigh])), "explore_random"
            return 4, "explore_stay"

    if unvisited[r, c]:
        return 4, "explore"
    gs = env.grid_size

    visited = np.zeros((gs, gs), dtype=bool)
    curdir = np.full((gs, gs), 4, dtype=np.int8)
    visited[r, c] = True
    cur = np.zeros((gs, gs), dtype=bool)
    cur[r, c] = True
    depth = 0

    while True:
        hit = cur & unvisited
        if hit.any():
            tr, tc = np.argwhere(hit)[0]
            return int(curdir[tr, tc]), "explore"

        depth += 1
        nxt = np.zeros((gs, gs), dtype=bool)
        nxt[:-1, :] |= cur[1:, :]   # up
        nxt[1:, :] |= cur[:-1, :]   # down
        nxt[:, :-1] |= cur[:, 1:]   # left
        nxt[:, 1:] |= cur[:, :-1]   # right
        nxt &= ~obs & ~visited
        if not nxt.any():
            break

        # Per-direction masks of newly reached cells (child -> parent).
        mu = np.zeros((gs, gs), dtype=bool); mu[:-1, :] = cur[1:, :]; mu &= nxt
        md = np.zeros((gs, gs), dtype=bool); md[1:, :] = cur[:-1, :]; md &= nxt
        ml = np.zeros((gs, gs), dtype=bool); ml[:, :-1] = cur[:, 1:]; ml &= nxt
        mr = np.zeros((gs, gs), dtype=bool); mr[:, 1:] = cur[:, :-1]; mr &= nxt

        if depth == 1:
            cd = np.full((gs, gs), 4, dtype=np.int8)
            cd[mu] = 0
            cd[md] = np.where(cd[md] == 4, 1, cd[md])
            cd[ml] = np.where(cd[ml] == 4, 2, cd[ml])
            cd[mr] = np.where(cd[mr] == 4, 3, cd[mr])
            curdir = cd
        else:
            nd = np.full((gs, gs), 4, dtype=np.int8)
            cand = np.full((gs, gs), 4, dtype=np.int8)
            cand[:-1, :] = np.where(mu[:-1, :], curdir[1:, :], 4)
            nd = np.minimum(nd, cand)
            cand = np.full((gs, gs), 4, dtype=np.int8)
            cand[1:, :] = np.where(md[1:, :], curdir[:-1, :], 4)
            nd = np.minimum(nd, cand)
            cand = np.full((gs, gs), 4, dtype=np.int8)
            cand[:, :-1] = np.where(ml[:, :-1], curdir[:, 1:], 4)
            nd = np.minimum(nd, cand)
            cand = np.full((gs, gs), 4, dtype=np.int8)
            cand[:, 1:] = np.where(mr[:, 1:], curdir[:, :-1], 4)
            nd = np.minimum(nd, cand)
            curdir = nd

        visited |= nxt
        cur = nxt

    env.explore_exhausted[agent_id] = True
    env.explore_exhausted_unvisited[agent_id] = unvisited.copy()
    env.explore_exhausted_obs[agent_id] = obs.copy()

    neigh = valid_neighbors_local(env, agent_id, r, c, include_stay=True)
    if neigh:
        return int(rng.choice([a for a, _, _ in neigh])), "explore_random"
    return 4, "explore_stay"


def exploit_action(env, agent_id, rng):
    """
    Move to the KNOWN neighbor with the lowest OWN visit count.
    Unknown cells are skipped for exploitation. Fallback: random move.
    Returns (action, mode).
    """
    r, c = env.agent_positions[agent_id]
    info = env.get_local_info(agent_id)
    visit = info["visit"].copy()
    obs = info["obs"]
    known = info["known"]

    visit[obs] = 999999
    best_actions = []
    best_score = -1.0

    for a, nr, nc in valid_neighbors_local(env, agent_id, r, c, include_stay=True):
        if not known[nr, nc]:
            continue
        score = 1.0 / (1.0 + visit[nr, nc])
        if a != 4:
            score += 0.1
        if score > best_score:
            best_score = score
            best_actions = [a]
        elif abs(score - best_score) < 1e-12:
            best_actions.append(a)

    if best_actions:
        return int(rng.choice(best_actions)), "exploit"

    neigh = valid_neighbors_local(env, agent_id, r, c, include_stay=True)
    if neigh:
        return int(rng.choice([a for a, _, _ in neigh])), "exploit"
    return 4, "exploit"


def box_sum(mask, w):
    """Sum of `mask` over every square window of radius `w` (size 2w+1),
    fully vectorized via two sliding cumsum passes. Returns a float grid."""
    f = np.asarray(mask, dtype=np.float64)

    def axis_sum(a, axis):
        n = a.shape[axis]
        A = np.pad(a, [(w, w) if ax == axis else (0, 0) for ax in range(2)],
                   mode="constant")
        zshape = list(A.shape)
        zshape[axis] = 1
        C = np.concatenate([np.zeros(zshape), np.cumsum(A, axis)], axis=axis)
        lo = np.arange(n)
        hi = lo + 2 * w + 1
        return np.take(C, hi, axis=axis) - np.take(C, lo, axis=axis)

    return axis_sum(axis_sum(f, 1), 0)


def bounded_bfs(env, agent_id, max_depth=8):
    """Bounded BFS from the agent in the V4 movement frame.

    Paths may pass through UNKNOWN cells and KNOWN-UNVISITED free cells, but
    NOT through already-visited cells. Every step into a target therefore
    enters fresh territory. Unknown cells are treated as free (codebase
    convention). The expansion is capped at `max_depth` layers, so the cost is
    bounded and independent of target distance.

    Returns (D, curdir):
      D[i, j]      = BFS layer (1..max_depth) or -1 if unreachable / beyond
                     the horizon
      curdir[i, j] = first-step action toward (i, j) (4 = stay/unset)
    """
    r, c = env.agent_positions[agent_id]
    known = env.get_known_mask(agent_id)
    obs = env.get_obstacle_knowledge(agent_id)
    visit = env.get_visit_knowledge(agent_id)
    gs = env.grid_size

    known_visited = known & ~obs & (visit > 0)
    free_path = ~obs & ~known_visited   # unknown + known-unvisited free cells

    visited = np.zeros((gs, gs), dtype=bool)
    visited[r, c] = True
    curdir = np.full((gs, gs), 4, dtype=np.int8)
    D = np.full((gs, gs), -1, dtype=np.int16)
    D[r, c] = 0
    cur = np.zeros((gs, gs), dtype=bool)
    cur[r, c] = True
    depth = 0

    while True:
        depth += 1
        if depth > max_depth:
            break
        nxt = np.zeros((gs, gs), dtype=bool)
        nxt[:-1, :] |= cur[1:, :]
        nxt[1:, :] |= cur[:-1, :]
        nxt[:, :-1] |= cur[:, 1:]
        nxt[:, 1:] |= cur[:, :-1]
        nxt &= free_path & ~visited
        if not nxt.any():
            break

        mu = np.zeros((gs, gs), dtype=bool); mu[:-1, :] = cur[1:, :]; mu &= nxt
        md = np.zeros((gs, gs), dtype=bool); md[1:, :] = cur[:-1, :]; md &= nxt
        ml = np.zeros((gs, gs), dtype=bool); ml[:, :-1] = cur[:, 1:]; ml &= nxt
        mr = np.zeros((gs, gs), dtype=bool); mr[:, 1:] = cur[:, :-1]; mr &= nxt

        if depth == 1:
            cd = np.full((gs, gs), 4, dtype=np.int8)
            cd[mu] = 0
            cd[md] = np.where(cd[md] == 4, 1, cd[md])
            cd[ml] = np.where(cd[ml] == 4, 2, cd[ml])
            cd[mr] = np.where(cd[mr] == 4, 3, cd[mr])
            curdir = cd
        else:
            nd = curdir.copy()
            cand = np.full((gs, gs), 4, dtype=np.int8)
            cand[:-1, :] = np.where(mu[:-1, :], curdir[1:, :], 4)
            nd = np.minimum(nd, cand)
            cand = np.full((gs, gs), 4, dtype=np.int8)
            cand[1:, :] = np.where(md[1:, :], curdir[:-1, :], 4)
            nd = np.minimum(nd, cand)
            cand = np.full((gs, gs), 4, dtype=np.int8)
            cand[:, :-1] = np.where(ml[:, :-1], curdir[:, 1:], 4)
            nd = np.minimum(nd, cand)
            cand = np.full((gs, gs), 4, dtype=np.int8)
            cand[:, 1:] = np.where(mr[:, 1:], curdir[:, :-1], 4)
            nd = np.minimum(nd, cand)
            curdir = nd

        D[nxt] = depth
        visited |= nxt
        cur = nxt

    return D, curdir


#====================================================================================================
# FILE   : policies/factory.py
# AIM    : Single construction point: canonical config names -> policy instances.
# DETAILS: Builds every method incl. 6 CentralOracle variants (crlb/config x cov/cov2/local). Unknown name -> ValueError.
#====================================================================================================

"""
policies/factory.py — Build any policy from a canonical method name.
Kept in ONE place so run_*.py and tests share identical construction.
"""

from policies.frontier import FrontierPolicy
from policies.greedy import GreedyPolicy
from policies.chao_u import ChaoUPolicy
from policies.entropy import EntropyPolicy, EntropyFracPolicy
from policies.frontier_entropy import FrontierEntropyPolicy
from policies.frontier_richness import FrontierRichnessPolicy
from policies.frontier_bounded import FrontierBoundedPolicy
from policies.random_walk import RandomPolicy
from policies.frontier_richness_angular import FrontierRichnessAngularPolicy
from policies.frontier_richness_deploy import FrontierRichnessDeployPolicy
from policies.coverage_u import CoverageUPolicy
from policies.central_oracle import CentralOraclePolicy


def build_policy(method_name, seed=None, fov_radius=5, K=0.5,
                 chao_variant=None, horizon=8, window=None, p_known=0.9,
                 eps=1.0, tie_eps=1e-3, lam=None):
    """
    method_name: one of the canonical names in config.py.
    Returns a fresh policy instance (never shared between agents).
    """
    from config import (METHOD_CHAO_U, METHOD_FRONTIER, METHOD_GREEDY,
                        METHOD_ENTROPY, METHOD_ENTROPY_FRAC,
                        METHOD_FRONTIER_ENTROPY, METHOD_FRONTIER_RICHNESS,
                        METHOD_FRONTIER_BOUNDED, METHOD_RANDOM,
                        METHOD_FRONTIER_RICHNESS_ANGULAR, METHOD_DEPLOY,
                        METHOD_COVERAGE_U,
                        METHOD_CENTRAL_CRLB, METHOD_CENTRAL_CONFIG,
                        METHOD_CENTRAL_CRLB_COV, METHOD_CENTRAL_CRLB_COV2,
                        METHOD_CENTRAL_CRLB_LOCAL, METHOD_CENTRAL_CONFIG_LOCAL,
                        DEPLOY_COOLDOWN, DEPLOY_UNDER_FRAC_MAX,
                        DEPLOY_MIN_UNDER_CELLS, DEPLOY_ORBIT_RADIUS,
                        DEPLOY_STATION_STEPS, DEPLOY_APPROACH_DEPTH,
                        COVERAGE_U_LAMBDA, CENTRAL_ORACLE_LAMBDA)

    common = dict(seed=seed, fov_radius=fov_radius, horizon=horizon,
                  window=window, p_known=p_known, eps=eps, tie_eps=tie_eps)
    richness_kw = {k: v for k, v in common.items() if k != "p_known"}

    if method_name == METHOD_FRONTIER:
        return FrontierPolicy(seed=seed, fov_radius=fov_radius)
    if method_name == METHOD_GREEDY:
        return GreedyPolicy(seed=seed, fov_radius=fov_radius)
    if method_name == METHOD_CHAO_U:
        return ChaoUPolicy(K=K, seed=seed, fov_radius=fov_radius,
                           variant=chao_variant or "original")
    if method_name == METHOD_ENTROPY:
        return EntropyPolicy(**common)
    if method_name == METHOD_ENTROPY_FRAC:
        return EntropyFracPolicy(**common)
    if method_name == METHOD_FRONTIER_ENTROPY:
        return FrontierEntropyPolicy(**common)
    if method_name == METHOD_FRONTIER_RICHNESS:
        return FrontierRichnessPolicy(**richness_kw)
    if method_name == METHOD_FRONTIER_BOUNDED:
        return FrontierBoundedPolicy(seed=seed, fov_radius=fov_radius,
                                     horizon=horizon, tie_eps=tie_eps)
    if method_name == METHOD_RANDOM:
        from config import RANDOM_REPULSION_DIST
        return RandomPolicy(seed=seed, fov_radius=fov_radius,
                            repulsion_dist=RANDOM_REPULSION_DIST)
    if method_name == METHOD_FRONTIER_RICHNESS_ANGULAR:
        return FrontierRichnessAngularPolicy(**richness_kw)
    if method_name == METHOD_DEPLOY:
        return FrontierRichnessDeployPolicy(
            seed=seed, fov_radius=fov_radius, horizon=horizon,
            cooldown=DEPLOY_COOLDOWN, under_frac_max=DEPLOY_UNDER_FRAC_MAX,
            min_under_cells=DEPLOY_MIN_UNDER_CELLS,
            orbit_radius=DEPLOY_ORBIT_RADIUS,
            station_steps=DEPLOY_STATION_STEPS,
            approach_depth=DEPLOY_APPROACH_DEPTH)
    if method_name == METHOD_COVERAGE_U:
        return CoverageUPolicy(seed=seed, fov_radius=fov_radius,
                               horizon=horizon, tie_eps=tie_eps,
                               lam=COVERAGE_U_LAMBDA if lam is None else lam)
    if method_name == METHOD_CENTRAL_CRLB:
        return CentralOraclePolicy(seed=seed, fov_radius=fov_radius,
                                   horizon=horizon, tie_eps=tie_eps,
                                   lam=CENTRAL_ORACLE_LAMBDA, mode="crlb")
    if method_name == METHOD_CENTRAL_CONFIG:
        return CentralOraclePolicy(seed=seed, fov_radius=fov_radius,
                                   horizon=horizon, tie_eps=tie_eps,
                                   lam=CENTRAL_ORACLE_LAMBDA, mode="config")
    if method_name == METHOD_CENTRAL_CRLB_COV:
        from config import CENTRAL_ORACLE_COV_GUARD_EPS
        return CentralOraclePolicy(seed=seed, fov_radius=fov_radius,
                                   horizon=horizon, tie_eps=tie_eps,
                                   lam=CENTRAL_ORACLE_LAMBDA, mode="crlb",
                                   coverage_guard_eps=CENTRAL_ORACLE_COV_GUARD_EPS)
    if method_name == METHOD_CENTRAL_CRLB_COV2:
        from config import CENTRAL_ORACLE_COV_GUARD_EPS2
        return CentralOraclePolicy(seed=seed, fov_radius=fov_radius,
                                   horizon=horizon, tie_eps=tie_eps,
                                   lam=CENTRAL_ORACLE_LAMBDA, mode="crlb",
                                   coverage_guard_eps=CENTRAL_ORACLE_COV_GUARD_EPS2)
    if method_name == METHOD_CENTRAL_CRLB_LOCAL:
        return CentralOraclePolicy(seed=seed, fov_radius=fov_radius,
                                   horizon=horizon, tie_eps=tie_eps,
                                   lam=CENTRAL_ORACLE_LAMBDA, mode="crlb",
                                   frame="local")
    if method_name == METHOD_CENTRAL_CONFIG_LOCAL:
        return CentralOraclePolicy(seed=seed, fov_radius=fov_radius,
                                   horizon=horizon, tie_eps=tie_eps,
                                   lam=CENTRAL_ORACLE_LAMBDA, mode="config",
                                   frame="local")

    raise ValueError(f"Unknown method: {method_name}")


#====================================================================================================
# FILE   : policies/frontier.py
# AIM    : V4 Frontier exploration baseline (control row).
# DETAILS: explore_action full-grid BFS to nearest locally-unvisited traversable cell; fallback random valid move.
#====================================================================================================

"""
policies/frontier.py — Frontier exploration: BFS to nearest locally-unvisited cell.
"""

import numpy as np
from policies._common import explore_action


class FrontierPolicy:
    def __init__(self, seed=None, fov_radius=5):
        self.rng = np.random.default_rng(seed)
        self.fov_radius = fov_radius
        self.random_walk = 0

    def select_action(self, env, agent_id):
        env.update_local_memory(agent_id, self.fov_radius)
        action, mode = explore_action(env, agent_id, self.rng)
        if mode == "explore_random":
            self.random_walk += 1
        return action, "frontier", mode, None


#====================================================================================================
# FILE   : policies/frontier_bounded.py
# AIM    : MOVEMENT-CONTROL diagnostic (NOT in the paper): Frontier selection inside bounded_bfs frame.
# DETAILS: Candidates = reachable unknown cells within horizon; picks min BFS layer, random ties; fallback explore_action. Byte-identical frame reused by Coverage-U/Deploy-U/oracle frame='local'.
#====================================================================================================

"""
policies/frontier_bounded.py — MOVEMENT CONTROL (temporary, NOT in the paper).

Isolates the effect of the movement frame from the effect of the signal.
Frontier-Bounded uses the entropy family's EXACT movement machinery
(bounded_bfs horizon R, fallback to explore_action when no candidate in the
horizon) but Frontier's selection rule: nearest reachable UNKNOWN cell
(min BFS layer), random tie-break. No utility, no window, no statistics.

If Frontier-Bounded ~ Frontier  : the bounded movement does not explain the
                                  family's gains -> signal-driven.
If Frontier-Bounded ~ Entropy   : a large part of the FOV=2/3 gain is a
                                  movement artifact, not the signal.
"""

import numpy as np

from policies._common import bounded_bfs, explore_action


class FrontierBoundedPolicy:
    def __init__(self, seed=None, fov_radius=5, horizon=8, tie_eps=1e-3):
        self.rng = np.random.default_rng(seed)
        self.fov_radius = fov_radius
        self.horizon = horizon
        self.tie_eps = tie_eps
        self.fallback = 0
        self.random_walk = 0

    def select_action(self, env, agent_id):
        env.update_local_memory(agent_id, self.fov_radius)
        info = env.get_local_info(agent_id)
        unknown = (~info["known"]).astype(np.float64)

        D, curdir = bounded_bfs(env, agent_id, max_depth=self.horizon)

        reachable = np.argwhere((D > 0) & unknown.astype(bool))
        if reachable.size == 0:
            self.fallback += 1
            action, mode = explore_action(env, agent_id, self.rng)
            if mode == "explore_random":
                self.random_walk += 1
            return action, "frontier_bounded", mode, None

        depth_min = D[reachable[:, 0], reachable[:, 1]].min()
        ties = reachable[D[reachable[:, 0], reachable[:, 1]] == depth_min]
        pick = ties[self.rng.integers(0, ties.shape[0])]
        tr, tc = int(pick[0]), int(pick[1])
        return int(curdir[tr, tc]), "frontier_bounded", "explore", None


#====================================================================================================
# FILE   : policies/frontier_richness.py
# AIM    : 'Frontier+Richness' V4 hybrid (visit-count signal, pre-Project08).
# DETAILS: utility = richness_map(visit,...)/(D+eps); U = F1(F1-1)/(2(F2+1)) capped at total_unknown, floored at 1; argmax with +/-tie_eps scatter.
#====================================================================================================

"""
policies/frontier_richness.py — Geometric + statistical-richness hybrid (V4).

Candidates = FRONTIER cells reachable within a bounded-BFS horizon R.
Utility = window Chao-U (bias_cap) richness of the candidate's neighborhood,
/ (BFS layer + eps). The first BFS step is the action.
"""

import numpy as np

from analysis.compute_entropy import (frontier_mask, richness_map,
                                      select_target)
from policies._common import bounded_bfs, explore_action


class FrontierRichnessPolicy:
    def __init__(self, seed=None, fov_radius=5, horizon=8, window=None,
                 eps=1.0, tie_eps=1e-3):
        self.rng = np.random.default_rng(seed)
        self.fov_radius = fov_radius
        self.horizon = horizon
        self.window = window if window is not None else fov_radius
        self.eps = eps
        self.tie_eps = tie_eps
        self.fallback = 0
        self.random_walk = 0

    def select_action(self, env, agent_id):
        env.update_local_memory(agent_id, self.fov_radius)
        info = env.get_local_info(agent_id)
        unknown = (~info["known"]).astype(np.float64)
        frontier = frontier_mask(info["known"], info["obs"], unknown)

        D, curdir = bounded_bfs(env, agent_id, max_depth=self.horizon)
        gain = richness_map(info["visit"], info["known"], info["obs"],
                            self.window, env.get_total_unknown(agent_id))

        utility = np.full_like(D, -np.inf, dtype=np.float64)
        pos = D > 0
        utility[pos] = gain[pos] / (D[pos] + self.eps)

        action = select_target(utility, D, curdir, frontier, self.rng,
                               tie_eps=self.tie_eps)
        if action is None:
            self.fallback += 1
            action, mode = explore_action(env, agent_id, self.rng)
            if mode == "explore_random":
                self.random_walk += 1
            return action, "Frontier+Richness", mode, None
        return int(action), "Frontier+Richness", "frontier_richness", None


#====================================================================================================
# FILE   : policies/frontier_richness_angular.py
# AIM    : 'Richness-Angular' Project08 Phase-1 hybrid: richness transposed to angular config counts.
# DETAILS: Same architecture as Frontier+Richness but counts = get_config_count_grid (local, fused); total_und = known-free cells with config<=1; argmax + tie_eps; fallback explore_action.
#====================================================================================================

"""
policies/frontier_richness_angular.py — Geometric + ANGULAR-richness hybrid.

The exact Frontier+Richness architecture of V4 (candidates = frontier cells
reachable within a bounded-BFS horizon R; utility = window Chao-U richness /
(BFS layer + eps)), with the richness signal transposed from visit counts to
independent angular configuration counts (Project08):
  - "visit"        := env.get_config_count_grid(agent) (local, fused),
  - F1 / F2        := cells with exactly 1 / 2 configurations,
  - U (bias_cap)   := F1(F1-1)/(2(F2+1)) capped at get_total_undetermined
                      (cells with 0 configurations).
The estimator and the window map are the LOCKED V4 functions, unchanged:
passing configuration counts as `visit` keeps them bit-coherent.
"""

import numpy as np

from analysis.compute_entropy import (frontier_mask, richness_map,
                                      select_target)
from policies._common import bounded_bfs, explore_action


class FrontierRichnessAngularPolicy:
    def __init__(self, seed=None, fov_radius=5, horizon=8, window=None,
                 eps=1.0, tie_eps=1e-3):
        self.rng = np.random.default_rng(seed)
        self.fov_radius = fov_radius
        self.horizon = horizon
        self.window = window if window is not None else fov_radius
        self.eps = eps
        self.tie_eps = tie_eps
        self.fallback = 0
        self.random_walk = 0

    def select_action(self, env, agent_id):
        env.update_local_memory(agent_id, self.fov_radius)
        info = env.get_local_info(agent_id)
        unknown = (~info["known"]).astype(np.float64)
        frontier = frontier_mask(info["known"], info["obs"], unknown)

        D, curdir = bounded_bfs(env, agent_id, max_depth=self.horizon)
        counts = env.get_config_count_grid(agent_id)
        total_und = env.get_total_undetermined(agent_id)
        gain = richness_map(counts, info["known"], info["obs"],
                            self.window, total_und)

        utility = np.full_like(D, -np.inf, dtype=np.float64)
        pos = D > 0
        utility[pos] = gain[pos] / (D[pos] + self.eps)

        action = select_target(utility, D, curdir, frontier, self.rng,
                               tie_eps=self.tie_eps)
        if action is None:
            self.fallback += 1
            action, mode = explore_action(env, agent_id, self.rng)
            if mode == "explore_random":
                self.random_walk += 1
            return action, "Richness-Angular", mode, None
        return int(action), "Richness-Angular", "frontier_richness_angular", None


