#====================================================================================================
# FILE   : experiments/trace.py
# AIM    : Replays one episode with on_step hook for qualitative figures.
# DETAILS: Records positions.npy, config_snapshots.npz at {0,T/4,T/2,3T/4,T}, f1_trace.csv, meta.json -> results/traces.
#====================================================================================================

"""
experiments/trace.py — replay one episode and RECORD what the raw CSV cannot
hold, for the qualitative figures (Figure A: trajectories + F1 overlay,
Figure B: config-count heatmaps, Figure C: F1-fraction(t)):

  - per-step agent positions (steps+1, num_agents, 2),
  - global config-count grids at sample steps (0, T/4, T/2, 3T/4, T),
  - ambiguous-fraction trace (fraction of traversable cells with exactly 1
    global angular configuration — observed but rank-deficient) at every step.

Deterministic: identical env_seed / policy seeds reproduce the campaign run.

Usage:
  python experiments/trace.py --method "Coverage-U" --run 0 --regime A3_obs005
                              --out-dir results/traces
"""

import argparse
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np

from config import (INFO_MODEL, GRID_SIZE, DEFAULT_FOV_RADIUS,
                    QUALITY_SAMPLE_K, QUALITY_TARGET)
from experiments._runner import run_episode
from utils.seed_manager import env_seed_for_run

REGIMES = {
    "A2_obs005": {"num_agents": 2, "obstacle_ratio": 0.05, "budget": 4200},
    "A3_obs005": {"num_agents": 3, "obstacle_ratio": 0.05, "budget": 3200},
    "A6_obs005": {"num_agents": 6, "obstacle_ratio": 0.05, "budget": 1600},
    "A6_obs020": {"num_agents": 6, "obstacle_ratio": 0.20, "budget": 1750},
}


class TraceRecorder:
    def __init__(self, sample_steps):
        self.sample_steps = sorted(set(sample_steps))
        self.positions = []
        self.steps = []
        self.ambiguous_frac = []
        self.snap_steps = []
        self.snap_grids = []

    def on_step(self, env, step):
        self.positions.append(
            np.asarray(env.agent_positions, dtype=np.int32).copy())
        self.steps.append(int(step))
        tr = ~env.obstacle_map
        cfg = env.global_config_count_grid()
        if int(step) in self.sample_steps:
            self.snap_steps.append(int(step))
            self.snap_grids.append(cfg.copy())
        ntr = env.traversable
        self.ambiguous_frac.append(
            float(np.sum((cfg == 1) & tr)) / ntr if ntr else 0.0)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--method", required=True)
    ap.add_argument("--run", type=int, required=True)
    ap.add_argument("--regime", required=True, choices=sorted(REGIMES))
    ap.add_argument("--out-dir", default=os.path.join("results", "traces"))
    ap.add_argument("--grid", type=int, default=GRID_SIZE)
    ap.add_argument("--fov", type=int, default=DEFAULT_FOV_RADIUS)
    args = ap.parse_args()

    rg = REGIMES[args.regime]
    T = rg["budget"]
    sample_steps = [0, T // 4, T // 2, 3 * T // 4, T]

    rec = TraceRecorder(sample_steps)
    env_seed = env_seed_for_run(args.run)
    res = run_episode(args.method, INFO_MODEL, args.run, env_seed,
                      grid_size=args.grid, num_agents=rg["num_agents"],
                      fov_radius=args.fov, obstacle_ratio=rg["obstacle_ratio"],
                      max_steps=T, quality_sample_k=QUALITY_SAMPLE_K,
                      quality_target=QUALITY_TARGET, on_step=rec.on_step)

    out = os.path.join(args.out_dir, args.regime,
                       f"{args.method.replace(' ', '_').replace('-', '_')}"
                       f"_run{args.run:02d}")
    os.makedirs(out, exist_ok=True)

    np.save(os.path.join(out, "positions.npy"),
            np.stack(rec.positions))
    np.savez(os.path.join(out, "config_snapshots.npz"),
             steps=np.asarray(rec.snap_steps),
             grids=np.stack(rec.snap_grids))
    with open(os.path.join(out, "f1_trace.csv"), "w") as fh:
        fh.write("step,ambiguous_frac\n")
        for s, f in zip(rec.steps, rec.ambiguous_frac):
            fh.write(f"{s},{f:.8f}\n")

    meta = {
        "method": args.method,
        "regime": args.regime,
        "run": args.run,
        "env_seed": env_seed,
        "budget": T,
        "num_agents": rg["num_agents"],
        "obstacle_ratio": rg["obstacle_ratio"],
        "grid_size": args.grid,
        "fov_radius": args.fov,
        "sample_steps": sample_steps,
        "final_coverage": res["final_coverage"],
        "mean_bound_final": res["mean_bound_final"],
        "quality_final": res["quality_final"],
        "quality_auc": res["quality_auc"],
        "undetermined_final": res["undetermined_final"],
    }
    with open(os.path.join(out, "meta.json"), "w") as fh:
        json.dump(meta, fh, indent=2)

    print(f"[trace] {args.method} run {args.run} {args.regime} -> {out}")
    print(f"  cov={res['final_coverage']:.1f}% mb={res['mean_bound_final']:.4f} "
          f"qfin={res['quality_final']:.3f} und={res['undetermined_final']:.3f}")


if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : experiments/fig_qualitative.py
# AIM    : Qualitative figures from traces: trajectories, config heatmaps, ambiguous-fraction curve.
# DETAILS: matplotlib Agg; hardcoded median/p75 runs per regime; FB vs CU colors.
#====================================================================================================

"""
experiments/fig_qualitative.py — render the FB-vs-CU qualitative figures from
the data recorded by experiments/trace.py.

Outputs (results/figures):
  fig_qualitative_traj.png   agent trajectories (rows: regime x percentile)
  fig_qualitative_config_A3_obs005.png  config-count heatmaps at t in {0,T/4,T/2,T}
  fig_qualitative_config_A6_obs005.png  (same for A6)
  fig_qualitative_f1.png     F1-fraction vs step

Requires the trace outputs already produced. Obstacle maps are rebuilt from
env_seed (deterministic), so no rerun of the episodes is needed here.
"""

import csv
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

from env import GridEnv
from config import INFO_MODEL, GRID_SIZE
from utils.seed_manager import env_seed_for_run

TRACE_ROOT = os.path.join("results", "traces")
FIG_OUT = os.path.join("results", "figures")
REGIMES = {
    "A3_obs005": {"num_agents": 3, "obstacle_ratio": 0.05,
                  "median_run": 26, "p75_run": 25},
    "A6_obs005": {"num_agents": 6, "obstacle_ratio": 0.05,
                  "median_run": 21, "p75_run": 12},
}
METHODS = ["Frontier-Bounded", "Coverage-U"]
FB_C = "#2c7bb6"
CU_C = "#d7191c"


def method_dir(method):
    return method.replace(" ", "_").replace("-", "_")


def load_trace(regime, method, run):
    base = os.path.join(TRACE_ROOT, regime, f"{method_dir(method)}_run{run:02d}")
    meta = json_load(os.path.join(base, "meta.json"))
    positions = np.load(os.path.join(base, "positions.npy"))
    snap = np.load(os.path.join(base, "config_snapshots.npz"))
    f1 = list(csv.DictReader(open(os.path.join(base, "f1_trace.csv"))))
    return (meta, positions, snap["steps"], snap["grids"],
            np.array([float(r["ambiguous_frac"]) for r in f1]))


def json_load(path):
    import json
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)


def obstacle_map(regime, run, grid=GRID_SIZE):
    rg = REGIMES[regime]
    env = GridEnv(grid_size=grid, num_agents=rg["num_agents"],
                  obstacle_ratio=rg["obstacle_ratio"],
                  seed=env_seed_for_run(run), info_model=INFO_MODEL)
    return env.obstacle_map


def draw_obstacles(ax, obs):
    ax.imshow(obs, cmap="Greys", vmin=0, vmax=1, alpha=0.35,
              interpolation="nearest")
    ax.set_xlim(-0.5, obs.shape[1] - 0.5)
    ax.set_ylim(obs.shape[0] - 0.5, -0.5)


def fig_trajectories():
    n_rows = len(REGIMES) * 2
    fig, axes = plt.subplots(n_rows, 2, figsize=(11, 4.6 * n_rows))
    r_i = 0
    for regime, rg in REGIMES.items():
        for lab, run in (("median", rg["median_run"]),
                         ("p75", rg["p75_run"])):
            obs = obstacle_map(regime, run)
            for c_i, method in enumerate(METHODS):
                meta, pos, _, _, _ = load_trace(regime, method, run)
                ax = axes[r_i, c_i]
                draw_obstacles(ax, obs)
                for a in range(pos.shape[1]):
                    ax.plot(pos[:, a, 1], pos[:, a, 0], lw=1.1, alpha=0.85)
                    ax.plot(pos[-1, a, 1], pos[-1, a, 0], "o", ms=6,
                            mfc="black", mec="white", mew=0.8)
                ax.set_title(
                    f"{method}\n{regime} run {run} ({lab})  "
                    f"m_bound={meta['mean_bound_final']:.4f}  "
                    f"cov={meta['final_coverage']:.0f}%", fontsize=10)
                ax.set_xticks([])
                ax.set_yticks([])
            r_i += 1
    fig.suptitle("Trajectories — Frontier-Bounded vs Coverage-U (comm-limited)",
                 fontsize=14, y=0.995)
    fig.tight_layout(rect=(0, 0, 1, 0.995))
    for ext in ("png", "pdf"):
        fig.savefig(os.path.join(FIG_OUT, f"fig_qualitative_traj.{ext}"),
                    dpi=200)
    plt.close(fig)
    print("[fig] fig_qualitative_traj.png")


def fig_config_heatmaps():
    steps_all = {}
    grids_all = {}
    for regime in REGIMES:
        steps_all[regime] = None
        grids_all[regime] = []
        for method in METHODS:
            run = REGIMES[regime]["median_run"]
            _, _, steps, grids, _ = load_trace(regime, method, run)
            steps_all[regime] = steps
            grids_all[regime].append(grids)
        vmax = max(int(g.max()) for g in grids_all[regime])
        vmax = min(vmax, 8)
        obs = obstacle_map(regime, REGIMES[regime]["median_run"])
        fig, axes = plt.subplots(len(METHODS), len(steps),
                                 figsize=(4.2 * len(steps), 4.6 * len(METHODS)))
        for r_i, method in enumerate(METHODS):
            for c_i, s in enumerate(steps):
                ax = axes[r_i, c_i]
                g = np.ma.masked_where(obs > 0, grids_all[regime][r_i][c_i])
                im = ax.imshow(g, cmap="viridis", vmin=0, vmax=vmax,
                               interpolation="nearest")
                ax.set_title(f"t={s}/{steps[-1]}", fontsize=10)
                if c_i == 0:
                    ax.set_ylabel(method, fontsize=10)
                ax.set_xticks([])
                ax.set_yticks([])
        cb = fig.colorbar(im, ax=axes.ravel().tolist(), fraction=0.025,
                          pad=0.02, label="global config count")
        cb.ax.tick_params(labelsize=8)
        fig.suptitle(f"Config-count snapshots — {regime} "
                     f"(run {REGIMES[regime]['median_run']})",
                     fontsize=13, y=0.995)
        fig.tight_layout(rect=(0, 0, 1, 0.97))
        for ext in ("png", "pdf"):
            fig.savefig(os.path.join(
                FIG_OUT, f"fig_qualitative_config_{regime}.{ext}"), dpi=200)
        plt.close(fig)
        print(f"[fig] fig_qualitative_config_{regime}.png")


def fig_f1():
    n_rows = len(REGIMES)
    fig, axes = plt.subplots(n_rows, 1, figsize=(8.5, 3.1 * n_rows))
    for r_i, (regime, rg) in enumerate(REGIMES.items()):
        ax = axes[r_i]
        for method, col in ((METHODS[0], FB_C), (METHODS[1], CU_C)):
            for lab, run, ls in (("median", rg["median_run"], "-"),
                                 ("p75", rg["p75_run"], "--")):
                _, _, _, _, f1 = load_trace(regime, method, run)
                T = len(f1) - 1
                ax.plot(np.arange(len(f1)), f1, ls, color=col, lw=1.4,
                        label=f"{method} ({lab})")
        ax.set_title(f"{regime}", fontsize=10)
        ax.set_xlabel("step")
        ax.set_ylabel("ambiguous fraction")
        ax.set_ylim(0, 0.10)
        ax.grid(alpha=0.25)
        ax.legend(fontsize=8, ncol=2, loc="center right")
    fig.suptitle("Fraction of traversable cells with exactly one global "
                 "angular configuration (observed but rank-deficient)",
                 fontsize=12, y=0.995)
    fig.tight_layout(rect=(0, 0, 1, 0.98))
    for ext in ("png", "pdf"):
        fig.savefig(os.path.join(FIG_OUT, f"fig_qualitative_f1.{ext}"), dpi=200)
    plt.close(fig)
    print("[fig] fig_qualitative_f1.png")


if __name__ == "__main__":
    os.makedirs(FIG_OUT, exist_ok=True)
    fig_trajectories()
    fig_config_heatmaps()
    fig_f1()


#====================================================================================================
# FILE   : experiments/run_baseline.py
# AIM    : V4 baseline campaign (comm_limited, 3 signal families) + CPU timing phase.
# DETAILS: Phase-1 methods Frontier/Greedy/Chao-U/Entropy/Entropy-Frac; Phase-2 hybrids via --phase2; own parallel harness; --cpu-timing forces serial + ms_per_decision.
#====================================================================================================

"""
run_baseline.py — V4 campaign: comm_limited, 3 signal families.

Protocol (locked decisions):
  - Grid 100x100, 6 agents, FOV=5, obstacles 5%, no noise, MAX_STEPS=10000.
  - NUM_RUNS=30 paired seeds (stride 1000).
  - Info model: comm_limited, R = FOV (comm_range follows fov).
  - Phase 1 methods: Frontier, Least-Visited Greedy, Chao-U (bias_cap),
    Entropy, Entropy-Frac. Phase 2 adds Frontier+Entropy, Frontier+Richness.
  - Movement: bounded-BFS (horizon R=8) through non-visited cells, identical
    frame for all new policies.

Usage:
  python experiments/run_baseline.py --methods Entropy --limit 1   # smoke
  python experiments/run_baseline.py                               # Phase 1
  python experiments/run_baseline.py --cpu-timing --methods Frontier,Entropy
"""

import argparse
import os
import sys
import time
from concurrent.futures import ProcessPoolExecutor, as_completed

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from config import (
    GRID_SIZE, NUM_AGENTS, MAX_STEPS, NUM_RUNS, DEFAULT_FOV_RADIUS,
    DEFAULT_OBSTACLE_RATIO, ADAPTIVE_K, NUM_WORKERS,
    METHOD_FRONTIER, METHOD_GREEDY, METHOD_CHAO_U,
    METHOD_ENTROPY, METHOD_ENTROPY_FRAC,
    METHOD_FRONTIER_ENTROPY, METHOD_FRONTIER_RICHNESS,
    ENTROPY_HORIZON, ENTROPY_WINDOW, SENSOR_RELIABILITY,
    UTILITY_EPSILON, TIE_BREAK_EPS, INFO_MODEL,
)
from experiments._runner import run_episode, RAW_CSV_FIELDS, TIMING_FIELDS
from utils.paths import raw_csv_path

OUT_DIR = "results/baseline"

# Phase 1 (validated individually before any hybrid is enabled).
PHASE1_METHODS = [
    METHOD_FRONTIER, METHOD_GREEDY, METHOD_CHAO_U,
    METHOD_ENTROPY, METHOD_ENTROPY_FRAC,
]

# Phase 2 (hybrids, enabled only after Phase 1 validation).
PHASE2_METHODS = [
    METHOD_FRONTIER_ENTROPY, METHOD_FRONTIER_RICHNESS,
]

CAMPAIGN_METHODS = PHASE1_METHODS + PHASE2_METHODS

# V2/V3 tuning (locked): Chao-U corrected variant.
CHAO_DEFAULT_VARIANT = "bias_cap"


def _cell_tag(info_model, fov_radius, obstacle_ratio, num_agents, comm_range,
              horizon=ENTROPY_HORIZON, window=ENTROPY_WINDOW, eps=UTILITY_EPSILON,
              p_known=SENSOR_RELIABILITY):
    """Filename tag encoding all NON-default dimensions of the cell."""
    if info_model != "comm_limited":
        return info_model
    parts = [info_model]
    if abs(float(fov_radius) - float(DEFAULT_FOV_RADIUS)) > 1e-9:
        parts.append(f"fov{float(fov_radius):g}")
    if abs(float(obstacle_ratio) - float(DEFAULT_OBSTACLE_RATIO)) > 1e-9:
        parts.append(f"obs{float(obstacle_ratio):g}")
    if num_agents != NUM_AGENTS:
        parts.append(f"agents{num_agents}")
    if (comm_range is not None
            and abs(float(comm_range) - float(fov_radius)) > 1e-9):
        parts.append(f"{float(comm_range):g}")
    if horizon != ENTROPY_HORIZON:
        parts.append(f"R{horizon}")
    if window is not None and window != DEFAULT_FOV_RADIUS:
        parts.append(f"w{window}")
    if abs(float(eps) - float(UTILITY_EPSILON)) > 1e-9:
        parts.append(f"eps{float(eps):g}")
    if abs(float(p_known) - float(SENSOR_RELIABILITY)) > 1e-9:
        parts.append(f"p{float(p_known):g}")
    return "@".join(parts)


def _csv_path(tag, method, variant=None):
    return raw_csv_path(OUT_DIR, tag, method, None, variant)


def _load_done(path):
    import csv
    done = {}
    if os.path.exists(path):
        with open(path, "r", encoding="utf-8") as f:
            for row in csv.DictReader(f):
                done[int(row["run"])] = row
    return done


def _fields(timing):
    return RAW_CSV_FIELDS + (TIMING_FIELDS if timing else [])


def _append_row(path, row, timing=False):
    fields = _fields(timing)
    new_file = not os.path.exists(path)
    with open(path, "a", newline="", encoding="utf-8") as f:
        import csv as _c
        w = _c.DictWriter(f, fieldnames=fields)
        if new_file:
            w.writeheader()
        w.writerow({k: row.get(k) for k in fields})


def main():
    global OUT_DIR
    ap = argparse.ArgumentParser()
    ap.add_argument("--info-model", type=str, default=INFO_MODEL)
    ap.add_argument("--comm-range", type=float, default=None,
                    help="comm_limited range in grid cells (default = fov)")
    ap.add_argument("--fov", type=int, default=DEFAULT_FOV_RADIUS)
    ap.add_argument("--obstacles", type=float, default=DEFAULT_OBSTACLE_RATIO)
    ap.add_argument("--agents", type=int, default=NUM_AGENTS)
    ap.add_argument("--out-dir", type=str, default=OUT_DIR)
    ap.add_argument("--methods", type=str, default=None,
                    help="comma-separated subset of campaign methods")
    ap.add_argument("--phase2", action="store_true",
                    help="include the Phase 2 hybrid methods")
    ap.add_argument("--chao-cap", action="store_true")
    ap.add_argument("--chao-bias", action="store_true")
    ap.add_argument("--chao-bias-cap", action="store_true")
    ap.add_argument("--horizon", type=int, default=ENTROPY_HORIZON,
                    help="bounded-BFS horizon R for the new policies")
    ap.add_argument("--window", type=int, default=ENTROPY_WINDOW,
                    help="signal window radius (default = FOV)")
    ap.add_argument("--p-known", type=float, default=SENSOR_RELIABILITY)
    ap.add_argument("--eps", type=float, default=UTILITY_EPSILON)
    ap.add_argument("--tie-eps", type=float, default=TIE_BREAK_EPS)
    ap.add_argument("--limit", type=int, default=None,
                    help="only run first N runs per cell (smoke test)")
    ap.add_argument("--workers", type=int, default=NUM_WORKERS)
    ap.add_argument("--cpu-timing", action="store_true",
                    help="CPU-timing phase: measure policy decision cost "
                         "(serial, results in results/cpu/)")
    args = ap.parse_args()

    timing = args.cpu_timing
    OUT_DIR = args.out_dir
    if timing:
        OUT_DIR = os.path.join(OUT_DIR, "cpu")
    os.makedirs(OUT_DIR, exist_ok=True)
    num_runs = args.limit if args.limit else NUM_RUNS
    t0 = time.time()

    info_model = args.info_model
    fov_radius = args.fov
    obstacle_ratio = args.obstacles
    num_agents = args.agents
    comm_range = args.comm_range
    if info_model == "comm_limited":
        comm_range = fov_radius if comm_range is None else comm_range
    else:
        comm_range = None

    if args.chao_cap:
        chao_variant = "cap"
    elif args.chao_bias:
        chao_variant = "bias"
    elif args.chao_bias_cap:
        chao_variant = "bias_cap"
    else:
        chao_variant = CHAO_DEFAULT_VARIANT

    candidates = CAMPAIGN_METHODS if args.phase2 else PHASE1_METHODS
    methods = (args.methods.split(",") if args.methods else list(candidates))

    tag = _cell_tag(info_model, fov_radius, obstacle_ratio, num_agents,
                    comm_range, args.horizon, args.window, args.eps,
                    args.p_known)
    if timing:
        tag = "cpu_" + tag
    workers = 1 if timing else args.workers
    print(f"=== V4 {'cpu-timing' if timing else 'campaign'}: {info_model} "
          f"[{tag}] FOV={fov_radius} obs={obstacle_ratio} agents={num_agents} "
          f"R={comm_range} horizon={args.horizon} window={args.window} ===",
          flush=True)
    for method in methods:
        variant = chao_variant if method == METHOD_CHAO_U else None
        path = _csv_path(tag, method, variant)
        done = _load_done(path)
        todo = [r for r in range(num_runs) if r not in done]
        if not todo:
            print(f"  {method}: already complete", flush=True)
            continue
        print(f"  {method}: {len(todo)} runs", flush=True)
        _run_parallel([(method, info_model, r, variant, comm_range,
                        fov_radius, obstacle_ratio, num_agents) for r in todo],
                      path, workers, timing, args.horizon, args.window,
                      args.p_known, args.eps, args.tie_eps)

    print(f"\nV4 {'cpu-timing' if timing else 'campaign'} done in "
          f"{time.time() - t0:.1f}s -> results in {OUT_DIR}", flush=True)


def _run_parallel(jobs, path, workers, timing=False, horizon=8, window=None,
                  p_known=0.9, eps=1.0, tie_eps=1e-3):
    """Run jobs (method, info_model, run, chao_variant, comm_range, fov_radius,
    obstacle_ratio, num_agents) in parallel, appending results incrementally
    from the main process. workers=1 runs inline (serial) so per-decision CPU
    timings are free of ProcessPool contention."""
    import csv
    from utils.seed_manager import env_seed_for_run

    queued = [(m, im, r, env_seed_for_run(r), cv, cr, fv, ob, na)
              for m, im, r, cv, cr, fv, ob, na in jobs]

    n = 0
    if workers == 1:
        for tup in queued:
            res = _run_one(tup, timing, horizon, window, p_known, eps, tie_eps)
            m, im, r = tup[0], tup[1], tup[2]
            n += 1
            _append_row(path, res, timing)
            print(f"    [{im} | {m}] run {r}: s90={res['steps_90']}, "
                  f"cov={res['final_coverage']:.1f}%, "
                  f"fus={res.get('fusion_events', 0)}, "
                  f"t={res['wall_time_s']:.1f}s, "
                  f"ms/d={res.get('ms_per_decision')} "
                  f"({n}/{len(jobs)} in this batch)", flush=True)
        return

    with ProcessPoolExecutor(max_workers=workers) as ex:
        futs = {ex.submit(_run_one, tup, timing, horizon, window, p_known,
                          eps, tie_eps): (tup[0], tup[1], tup[2]) for tup in queued}
        for fut in as_completed(futs):
            res = fut.result()
            m, im, r = futs[fut]
            n += 1
            _append_row(path, res, timing)
            print(f"    [{im} | {m}] run {r}: s90={res['steps_90']}, "
                  f"cov={res['final_coverage']:.1f}%, "
                  f"fus={res.get('fusion_events', 0)}, "
                  f"t={res['wall_time_s']:.1f}s "
                  f"({n}/{len(jobs)} in this batch)", flush=True)


def _run_one(tup, timing=False, horizon=8, window=None, p_known=0.9,
             eps=1.0, tie_eps=1e-3):
    """Module-level picklable worker: one episode."""
    m, im, r, es, cv, cr, fv, ob, na = tup
    return run_episode(m, im, r, es, fov_radius=fv,
                       K=ADAPTIVE_K, grid_size=GRID_SIZE, num_agents=na,
                       obstacle_ratio=ob, max_steps=MAX_STEPS,
                       chao_variant=cv, comm_range=cr, timing=timing,
                       horizon=horizon, window=window, p_known=p_known,
                       eps=eps, tie_eps=tie_eps)


if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : analysis/budget_stats.py
# AIM    : E4 + E4-CONFIRM statistics: Coverage-U vs FB under budget, verdict logic.
# DETAILS: PRIMARY quality_auc, GUARD final_coverage, SECONDARY mean_bound_final etc. E4-CONFIRM: primaire mean_bound_final, n=40, PASS iff rel-red>=10% AND Holm-sig AND no coverage regression.
#====================================================================================================

"""
analysis/budget_stats.py — E4 A/B statistics: Coverage-U vs Frontier-Bounded
under a finite mission budget (plus Deploy-U context row).

Primary (pre-registered): quality_auc @ budget T (integrated accuracy under the
mission, higher better). Guard: final_coverage @ T must NOT be significantly
worse (Pareto-clean check). Secondary: mean_bound_final @ T (lower better),
undetermined_final @ T (lower better), steps_dual (lower better), coverage_auc
(higher better).

Protocol (locked, mirrors deploy_stats):
  - Paired Wilcoxon (zero_method="wilcox") per regime.
  - Holm-Bonferroni across the 4 regimes (global).
  - Delta = matched-pairs statistic m/n^2 (positive = A better).
  - Median relative gain of A over B (sign flipped for lower-is-better).

A4 verdict (E4): median quality_auc gain >= 8% AND any Holm-sig on quality_auc
AND no Holm-sig coverage regression.

Usage:
  python analysis/budget_stats.py
"""

import csv
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np
from scipy import stats

from config import (METHOD_FRONTIER_BOUNDED, METHOD_DEPLOY, METHOD_COVERAGE_U)

REGIMES = ["A2_obs005", "A3_obs005", "A6_obs005", "A6_obs020"]
RESULTS_DIR = os.path.join(os.path.dirname(os.path.dirname(
    os.path.abspath(__file__))), "results")

PRIMARY = "quality_auc"
GUARD = "final_coverage"
SECONDARY = ["coverage_auc", "mean_bound_final", "undetermined_final",
             "steps_dual", "time_to_quality"]
# lower-is-better metrics (positive gain = A better when smaller)
LOWER_BETTER = {"mean_bound_final", "undetermined_final", "steps_dual",
                "time_to_quality"}
MIN_GAIN_PCT = 8.0  # A4 preregistered threshold


def sanitize(method):
    return re.sub(r"[^\w\-]", "_", method)


def load(dir_path, method):
    path = os.path.join(dir_path, f"raw_comm_limited__{sanitize(method)}.csv")
    if not os.path.exists(path):
        return None
    with open(path, "r", encoding="utf-8") as fh:
        rows = list(csv.DictReader(fh))
    rows.sort(key=lambda r: int(r.get("run", 0)))
    return rows


def _num(r, key, cap=None):
    v = r.get(key)
    if v in (None, ""):
        return cap
    try:
        return float(v)
    except ValueError:
        return cap


def metric_vector(rows, metric, cap):
    return np.array([_num(r, metric, cap) for r in rows], dtype=float)


def paired_stats(a, b):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    if len(a) != len(b) or len(a) == 0:
        return float("nan"), 0.0
    d = a - b
    if np.all(np.abs(d) < 1e-12):
        return 1.0, 0.0
    try:
        _, p = stats.wilcoxon(a, b, zero_method="wilcox")
    except ValueError:
        return 1.0, 0.0
    n = len(a)
    m = 0.0
    for i in range(n):
        m += np.sum(a[i] > b) - np.sum(a[i] < b)
    return float(p), m / (n * n)


def holm_bonferroni(ps):
    n = len(ps)
    order = np.argsort(ps)
    out = [None] * n
    for rank, idx in enumerate(order):
        out[idx] = min(1.0, ps[idx] * (n - rank))
    for i in range(n - 1, 0, -1):
        out[order[i - 1]] = min(out[order[i - 1]], out[order[i]])
    return out


def gain_pct(va, vb, lower_better):
    """Median relative gain of A over B; positive = A better."""
    if lower_better:
        num, den = vb - va, va
    else:
        num, den = va - vb, vb
    return float(np.nanmedian(num / np.where(den == 0, np.nan, den)) * 100.0)


def main():
    data = {}
    for rg in REGIMES:
        d = os.path.join(RESULTS_DIR, f"budget_{rg}")
        rows = {}
        for m in (METHOD_FRONTIER_BOUNDED, METHOD_DEPLOY, METHOD_COVERAGE_U):
            r = load(d, m)
            if r is None or not r:
                print(f"WARNING incomplete regime {rg}, method {m}: "
                      f"{0 if r is None else len(r)} runs")
                r = []
            rows[m] = r
        if rows[METHOD_FRONTIER_BOUNDED] and rows[METHOD_COVERAGE_U]:
            data[rg] = rows

    print(f"# E4 A/B: {METHOD_COVERAGE_U} vs {METHOD_FRONTIER_BOUNDED} "
          f"(paired, budget-limited; {METHOD_DEPLOY} as context)")
    print(f"# PRIMARY: {PRIMARY} @ budget (higher better)\n")

    # --- primary table (Coverage-U vs FB) ---
    rows = []
    for rg in REGIMES:
        if rg not in data:
            continue
        a = data[rg][METHOD_COVERAGE_U]
        b = data[rg][METHOD_FRONTIER_BOUNDED]
        va = metric_vector(a, PRIMARY, -1.0)
        vb = metric_vector(b, PRIMARY, -1.0)
        p, d = paired_stats(va, vb)
        med_a, med_b = np.median(va), np.median(vb)
        g = gain_pct(va, vb, lower_better=False)
        rows.append((rg, med_a, med_b, g, p, d))
    ps = [r[4] for r in rows]
    corrected = holm_bonferroni(ps)

    print(f"# PRIMARY {PRIMARY} (median), Coverage-U vs FB")
    print(f"{'regime':<12} {'med_FB':>8} {'med_CU':>8} {'gain%':>7} "
          f"{'p':>8} {'p_holm':>8} {'delta':>7} {'sig':>5}")
    print("-" * 72)
    for (rg, med_a, med_b, g, p, d), pc in zip(rows, corrected):
        sig = "YES" if pc < 0.05 else "no"
        print(f"{rg:<12} {med_b:>8.3f} {med_a:>8.3f} {g:>+7.1f} "
              f"{p:>8.4f} {pc:>8.4f} {d:>+7.3f} {sig:>5}")

    # --- coverage guard (Pareto-clean check) ---
    grow = []
    for rg in REGIMES:
        if rg not in data:
            continue
        a = data[rg][METHOD_COVERAGE_U]
        b = data[rg][METHOD_FRONTIER_BOUNDED]
        va = metric_vector(a, GUARD, -1.0)
        vb = metric_vector(b, GUARD, -1.0)
        p, _ = paired_stats(va, vb)
        med_a, med_b = np.median(va), np.median(vb)
        grow.append((rg, med_a, med_b, p))
    gps = [r[3] for r in grow]
    gcorr = holm_bonferroni(gps)
    print(f"\n# GUARD: {GUARD} @ budget (Coverage-U must not be significantly "
          f"worse)")
    print(f"{'regime':<12} {'med_FB':>8} {'med_CU':>8} {'p':>8} "
          f"{'p_holm':>8} {'regression?':>12}")
    print("-" * 60)
    regress = False
    for (rg, med_a, med_b, p), pc in zip(grow, gcorr):
        is_r = pc < 0.05 and med_a < med_b
        regress |= is_r
        print(f"{rg:<12} {med_b:>8.1f} {med_a:>8.1f} {p:>8.4f} {pc:>8.4f} "
              f"{'YES' if is_r else 'no':>12}")

    # --- A4 verdict ---
    if rows:
        gains = [r[3] for r in rows]
        med_gain = float(np.median(gains))
        any_sig = any(pc < 0.05 for pc in corrected)
        passed = med_gain >= MIN_GAIN_PCT and any_sig and not regress
        print()
        print(f"# A4 verdict (primary={PRIMARY}): median gain = {med_gain:+.1f}% "
              f"(threshold {MIN_GAIN_PCT:+.0f}%), any Holm-sig = {any_sig}, "
              f"coverage regression = {regress}")
        print(f"#   => {'PASS' if passed else 'FAIL'}")

    # --- secondary metrics (Coverage-U vs FB) ---
    print("\n# Secondary metrics, Coverage-U vs FB (gain% = Coverage-U better)")
    print(f"{'metric':<18} {'regime':<12} {'med_FB':>8} {'med_CU':>8} "
          f"{'gain%':>7}")
    print("-" * 60)
    for metric in SECONDARY:
        lb = metric in LOWER_BETTER
        for rg in REGIMES:
            if rg not in data:
                continue
            a = data[rg][METHOD_COVERAGE_U]
            b = data[rg][METHOD_FRONTIER_BOUNDED]
            va = metric_vector(a, metric, None)
            vb = metric_vector(b, metric, None)
            if np.all(np.isnan(va)) or np.all(np.isnan(vb)):
                continue
            med_a, med_b = np.nanmedian(va), np.nanmedian(vb)
            g = gain_pct(va, vb, lb)
            print(f"{metric:<18} {rg:<12} {med_b:>8.3f} {med_a:>8.3f} "
                  f"{g:>+7.1f}")

    # --- accuracy secondaries with paired tests ---
    # quality_auc is a coarse binary (>=2 configs) saturation measure; the
    # continuous accuracy metrics (mean_bound_final, undetermined_final) carry
    # the precision signal directly. Report their paired tests explicitly.
    print("\n# Accuracy secondaries, paired (Coverage-U vs FB; gain = "
          "Coverage-U better)")
    for metric in ("mean_bound_final", "undetermined_final"):
        print(f"\n  {metric} (lower better)")
        arows = []
        for rg in REGIMES:
            if rg not in data:
                continue
            a = data[rg][METHOD_COVERAGE_U]
            b = data[rg][METHOD_FRONTIER_BOUNDED]
            va = metric_vector(a, metric, None)
            vb = metric_vector(b, metric, None)
            if np.all(np.isnan(va)) or np.all(np.isnan(vb)):
                continue
            p, d = paired_stats(va, vb)
            g = gain_pct(va, vb, lower_better=True)
            arows.append((rg, np.nanmedian(va), np.nanmedian(vb), g, p, d))
        aps = [r[4] for r in arows]
        acorr = holm_bonferroni(aps)
        print(f"    {'regime':<12} {'med_FB':>9} {'med_CU':>9} {'gain%':>8} "
              f"{'p':>8} {'p_holm':>8} {'delta':>7} {'sig':>5}")
        for (rg, ma, mb, g, p, d), pc in zip(arows, acorr):
            print(f"    {rg:<12} {mb:>9.4f} {ma:>9.4f} {g:>+8.1f} {p:>8.4f} "
                  f"{pc:>8.4f} {d:>+7.3f} {'YES' if pc < 0.05 else 'no':>5}")

    # --- E4-CONFIRM: pre-registered higher-power verdict on the accuracy
    # primary. E4's preregistered primary (quality_auc) failed (saturated binary
    # fraction); the coherent directional effect was on mean_bound_final @ T.
    # Confirmation campaign: n=40 pairs/regime (30 new seed-pairs appended),
    # methods FB + Coverage-U only, same budgets T. Pre-registered success:
    #   (i) median relative reduction of mean_bound_final rel. FB >= 10%,
    #   (ii) any Holm-sig on mean_bound_final @ T across the 4 regimes,
    #   (iii) no Holm-sig coverage regression.
    # Fisher combined p across the 4 regimes reported as a global statement.
    print("\n# E4-CONFIRM: higher-power verdict on mean_bound_final @ T "
          "(rel-FB reduction)")
    for metric in ("mean_bound_final",):
        prow = []
        for rg in REGIMES:
            if rg not in data:
                continue
            a = data[rg][METHOD_COVERAGE_U]
            b = data[rg][METHOD_FRONTIER_BOUNDED]
            va = metric_vector(a, metric, None)
            vb = metric_vector(b, metric, None)
            if np.all(np.isnan(va)) or np.all(np.isnan(vb)):
                continue
            p, d = paired_stats(va, vb)
            med_a, med_b = np.nanmedian(va), np.nanmedian(vb)
            rel = (med_b - med_a) / med_b * 100.0
            prow.append((rg, med_a, med_b, rel, p, d))
        cps = [r[4] for r in prow]
        cholm = holm_bonferroni(cps)
        print(f"    {'regime':<12} {'med_FB':>9} {'med_CU':>9} "
              f"{'rel-red%':>9} {'p':>8} {'p_holm':>8} {'delta':>7} {'sig':>5}")
        for (rg, ma, mb, rel, p, d), pc in zip(prow, cholm):
            print(f"    {rg:<12} {mb:>9.4f} {ma:>9.4f} {rel:>+9.1f} {p:>8.4f} "
                  f"{pc:>8.4f} {d:>+7.3f} {'YES' if pc < 0.05 else 'no':>5}")
        rels = [r[3] for r in prow]
        med_rel = float(np.nanmedian(rels))
        any_sig = any(pc < 0.05 for pc in cholm)
        if len(cps) >= 2 and all(p > 0 for p in cps):
            chi2 = -2.0 * np.sum(np.log(np.maximum(cps, 1e-300)))
            f_p = float(1.0 - stats.chi2.cdf(chi2, 2 * len(cps)))
        else:
            f_p = float("nan")
        # guard: coverage regression on the full (appended) sample
        cov_reg = False
        for rg in REGIMES:
            if rg not in data:
                continue
            va = metric_vector(data[rg][METHOD_COVERAGE_U], GUARD, -1.0)
            vb = metric_vector(data[rg][METHOD_FRONTIER_BOUNDED], GUARD, -1.0)
            p, _ = paired_stats(va, vb)
            if p < 0.05 and np.nanmedian(va) < np.nanmedian(vb):
                cov_reg = True
        passed = med_rel >= 10.0 and any_sig and not cov_reg
        print(f"\n    median rel-reduction = {med_rel:+.1f}% (threshold +10%), "
              f"any Holm-sig = {any_sig}, coverage regression = {cov_reg}, "
              f"Fisher combined p = {f_p:.4f}")
        print(f"    => {'PASS' if passed else 'FAIL'} (E4-CONFIRM)")

    # --- context: Deploy-U vs FB on primary ---
    print("\n# Context: Deploy-U vs FB on PRIMARY (from the same budget data)")
    print(f"{'regime':<12} {'med_FB':>8} {'med_DU':>8} {'gain%':>7}")
    print("-" * 40)
    for rg in REGIMES:
        if rg not in data or not data[rg][METHOD_DEPLOY]:
            continue
        a = data[rg][METHOD_DEPLOY]
        b = data[rg][METHOD_FRONTIER_BOUNDED]
        # Deploy-U exists only on the original 10 seed-pairs (0-9); restrict FB
        # to the same run indices so the context comparison stays paired.
        du_runs = {int(r.get("run", -1)) for r in a}
        fb = [r for r in b if int(r.get("run", -1)) in du_runs]
        va = metric_vector(a, PRIMARY, -1.0)
        vb = metric_vector(fb, PRIMARY, -1.0)
        g = gain_pct(va, vb, lower_better=False)
        print(f"{rg:<12} {np.median(vb):>8.3f} {np.median(va):>8.3f} "
              f"{g:>+7.1f}")


if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : analysis/e5_stats.py
# AIM    : E5 + E5-DIAG + E5-CORRECTED statistics: centralized oracle ladder, guard check, corrected verdict.
# DETAILS: Ladder FB->CU->Config->CRLB, transposition ratio rho. E5 VERDICT FAIL. E5-DIAG: guarded variants bit-identical (guard never binds). E5-CORRECTED outcome B: local signal beats global oracles even with matched frame (p<1e-8).
#====================================================================================================

"""
analysis/e5_stats.py — E5: centralized oracle upper bound + transposition ratio.

Question: how much of the accuracy gain of a centralized perfect oracle does the
decentralized config-count signal (Coverage-U) capture? Pre-registered in
PRE_REG_E5.md (verdict PASS conditions below).

Protocol (locked):
  - Regimes A3_obs005, A6_obs005 (E4-PARETO selection); n = 40 paired runs.
  - Primary: mean_bound_final @ T, median relative reduction vs Frontier-Bounded
    (lower better).
  - Ladder: FB -> Coverage-U (λ=0.5) -> CentralOracle-Config -> CentralOracle-CRLB.
  - Transposition ratio per regime: rho = reduction_CoverageU /
    reduction_CentralOracleCRLB (medians, rel. FB).
  - Paired Wilcoxon (zero_method="wilcox"), Holm-Bonferroni across the 2
    regimes, per method.
  - Guard: final_coverage @ T must not regress (Holm-sig) for either oracle row.

E5 verdict (pre-registered): PASS iff in BOTH regimes
  (1) reduction_CentralCRLB >= reduction_CoverageU,
  (2) rho >= 0.5,
  (3) no Holm-sig coverage regression (oracle vs FB).
Secondary diagnostics (not verdict): ladder gap CentralCRLB - CentralConfig
(proxy cost even at perfect fusion) and CentralConfig - CoverageU (value of
perfect fusion).

Usage:
  python analysis/e5_stats.py
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np

from config import (METHOD_FRONTIER_BOUNDED, METHOD_COVERAGE_U,
                    METHOD_CENTRAL_CRLB, METHOD_CENTRAL_CONFIG,
                    METHOD_CENTRAL_CRLB_COV, METHOD_CENTRAL_CRLB_COV2,
                    METHOD_CENTRAL_CRLB_LOCAL, METHOD_CENTRAL_CONFIG_LOCAL)
from analysis.budget_stats import (load, metric_vector, paired_stats,
                                   holm_bonferroni, gain_pct)

REGIMES = ["A3_obs005", "A6_obs005"]
RESULTS_DIR = os.path.join(os.path.dirname(os.path.dirname(
    os.path.abspath(__file__))), "results")

PRIMARY = "mean_bound_final"     # lower better
GUARD = "final_coverage"         # higher better, must not regress
SUPPORT = "undetermined_final"   # lower better
SECONDARY = "quality_auc"        # higher better


def _reduction(rg, rows_a, rows_b, metric):
    va = metric_vector(rows_a, metric, float("nan"))
    vb = metric_vector(rows_b, metric, float("nan"))
    return gain_pct(va, vb, lower_better=True)  # med rel gain of A over B


def main():
    methods = [METHOD_FRONTIER_BOUNDED, METHOD_COVERAGE_U,
               METHOD_CENTRAL_CONFIG, METHOD_CENTRAL_CRLB,
               METHOD_CENTRAL_CRLB_LOCAL, METHOD_CENTRAL_CONFIG_LOCAL]
    data = {}
    for rg in REGIMES:
        d = os.path.join(RESULTS_DIR, f"budget_{rg}")
        rows = {}
        for m in methods:
            r = load(d, m)
            if r is None or not r:
                print(f"WARNING incomplete regime {rg}, method {m}: "
                      f"{0 if r is None else len(r)} runs")
                r = []
            rows[m] = r
        if rows[METHOD_FRONTIER_BOUNDED] and rows[METHOD_CENTRAL_CRLB]:
            data[rg] = rows

    missing = [rg for rg in REGIMES if rg not in data]
    if missing:
        print(f"# SKIPPED (incomplete oracle data): {', '.join(missing)}")
    done_rgs = [rg for rg in REGIMES if rg in data]
    if not done_rgs:
        print("Nothing to analyse yet.")
        return

    print("# E5: centralized oracle upper bound vs decentralized Coverage-U")
    print("# Primary: mean_bound_final @ T, median rel. reduction vs FB "
          "(lower better)\n")

    # ---- ladder table ----
    print(f"{'regime':<12} {'FB':>8} {'CU':>8} {'CentConfig':>10} "
          f"{'CentCRLB':>9} | {'red_CU%':>8} {'red_Conf%':>9} "
          f"{'red_CRLB%':>9} {'rho':>6}")
    print("-" * 92)
    reductions = {rg: {} for rg in done_rgs}
    for rg in done_rgs:
        rows = data[rg]
        meds = {}
        for m in methods:
            meds[m] = np.nanmedian(metric_vector(rows[m], PRIMARY, float("nan")))
        red = {}
        for m in (METHOD_COVERAGE_U, METHOD_CENTRAL_CONFIG, METHOD_CENTRAL_CRLB):
            red[m] = _reduction(rg, rows[m], rows[METHOD_FRONTIER_BOUNDED],
                                PRIMARY)
        reductions[rg] = red
        rho = red[METHOD_COVERAGE_U] / red[METHOD_CENTRAL_CRLB] \
            if red[METHOD_CENTRAL_CRLB] > 0 else float("nan")
        print(f"{rg:<12} {meds[METHOD_FRONTIER_BOUNDED]:>8.3f} "
              f"{meds[METHOD_COVERAGE_U]:>8.3f} "
              f"{meds[METHOD_CENTRAL_CONFIG]:>10.3f} "
              f"{meds[METHOD_CENTRAL_CRLB]:>9.3f} | "
              f"{red[METHOD_COVERAGE_U]:>+8.1f} "
              f"{red[METHOD_CENTRAL_CONFIG]:>+9.1f} "
              f"{red[METHOD_CENTRAL_CRLB]:>+9.1f} {rho:>6.2f}")

    # ---- primary significance vs FB, Holm per method across regimes ----
    print("\n# Paired Wilcoxon vs FB on mean_bound_final (Holm across 2 regimes)")
    print(f"{'method':<24} {'regime':<12} {'p':>8} {'p_holm':>8} {'sig':>5}")
    print("-" * 62)
    holm_map = {}
    for m in (METHOD_COVERAGE_U, METHOD_CENTRAL_CONFIG, METHOD_CENTRAL_CRLB):
        ps = []
        for rg in done_rgs:
            va = metric_vector(data[rg][m], PRIMARY, float("nan"))
            vb = metric_vector(data[rg][METHOD_FRONTIER_BOUNDED], PRIMARY,
                               float("nan"))
            p, _ = paired_stats(va, vb)
            ps.append(p)
        holm_map[m] = holm_bonferroni(ps)
        for rg, p, pc in zip(done_rgs, ps, holm_map[m]):
            print(f"{m:<24} {rg:<12} {p:>8.4f} {pc:>8.4f} "
                  f"{'YES' if pc < 0.05 else 'no':>5}")

    # ---- ladder gap: CentralCRLB vs CentralConfig (proxy cost) ----
    print("\n# Ladder gap: CentralOracle-CRLB vs CentralOracle-Config "
          "(Holm across regimes)")
    print(f"{'regime':<12} {'p':>8} {'p_holm':>8} {'sig':>5}")
    print("-" * 40)
    ps = []
    for rg in done_rgs:
        va = metric_vector(data[rg][METHOD_CENTRAL_CRLB], PRIMARY, float("nan"))
        vb = metric_vector(data[rg][METHOD_CENTRAL_CONFIG], PRIMARY, float("nan"))
        p, _ = paired_stats(va, vb)
        ps.append(p)
    for rg, p, pc in zip(done_rgs, ps, holm_bonferroni(ps)):
        print(f"{rg:<12} {p:>8.4f} {pc:>8.4f} {'YES' if pc < 0.05 else 'no':>5}")

    # ---- coverage guard ----
    print(f"\n# GUARD: {GUARD} @ T vs FB (Holm across regimes, regression if "
          f"p_holm<0.05 and median lower)")
    print(f"{'method':<24} {'regime':<12} {'med':>8} {'med_FB':>8} {'p':>8} "
          f"{'p_holm':>8} {'reg?':>5}")
    print("-" * 76)
    for m in (METHOD_COVERAGE_U, METHOD_CENTRAL_CONFIG, METHOD_CENTRAL_CRLB):
        gps = []
        for rg in done_rgs:
            va = metric_vector(data[rg][m], GUARD, float("nan"))
            vb = metric_vector(data[rg][METHOD_FRONTIER_BOUNDED], GUARD,
                               float("nan"))
            p, _ = paired_stats(va, vb)
            gps.append(p)
        gcorr = holm_bonferroni(gps)
        for rg, p, pc in zip(done_rgs, gps, gcorr):
            med_a = np.nanmedian(metric_vector(data[rg][m], GUARD, float("nan")))
            med_b = np.nanmedian(metric_vector(data[rg][METHOD_FRONTIER_BOUNDED],
                                               GUARD, float("nan")))
            reg = "YES" if (pc < 0.05 and med_a < med_b) else "no"
            print(f"{m:<24} {rg:<12} {med_a:>8.1f} {med_b:>8.1f} {p:>8.4f} "
                  f"{pc:>8.4f} {reg:>5}")

    # ---- support + secondary ----
    print(f"\n# SUPPORT: {SUPPORT} @ T, median rel. reduction vs FB")
    print(f"{'regime':<12} {'CU%':>8} {'CentConfig%':>12} {'CentCRLB%':>10}")
    print("-" * 46)
    for rg in done_rgs:
        row = []
        for m in (METHOD_COVERAGE_U, METHOD_CENTRAL_CONFIG, METHOD_CENTRAL_CRLB):
            row.append(_reduction(rg, data[rg][m],
                                  data[rg][METHOD_FRONTIER_BOUNDED], SUPPORT))
        print(f"{rg:<12} {row[0]:>+8.1f} {row[1]:>+12.1f} {row[2]:>+10.1f}")

    # ---- verdict ----
    print("\n# E5 VERDICT (pre-registered)")
    ok = True
    for rg in done_rgs:
        r = reductions[rg]
        rho = r[METHOD_COVERAGE_U] / r[METHOD_CENTRAL_CRLB] \
            if r[METHOD_CENTRAL_CRLB] > 0 else float("nan")
        c1 = r[METHOD_CENTRAL_CRLB] >= r[METHOD_COVERAGE_U]
        c2 = rho >= 0.5
        print(f"{rg}: red_CRLB={r[METHOD_CENTRAL_CRLB]:+.1f}% >= "
              f"red_CU={r[METHOD_COVERAGE_U]:+.1f}% -> {c1}; "
              f"rho={rho:.2f} >= 0.5 -> {c2}")
        ok = ok and c1 and c2
    # coverage guard check
    guard_ok = True
    for m in (METHOD_CENTRAL_CONFIG, METHOD_CENTRAL_CRLB):
        gps = []
        for rg in done_rgs:
            va = metric_vector(data[rg][m], GUARD, float("nan"))
            vb = metric_vector(data[rg][METHOD_FRONTIER_BOUNDED], GUARD,
                               float("nan"))
            p, _ = paired_stats(va, vb)
            gps.append(p)
        for rg, p in zip(done_rgs, gps):
            if holm_bonferroni(gps)[done_rgs.index(rg)] < 0.05:
                med_a = np.nanmedian(metric_vector(data[rg][m], GUARD,
                                                   float("nan")))
                med_b = np.nanmedian(metric_vector(
                    data[rg][METHOD_FRONTIER_BOUNDED], GUARD, float("nan")))
                if med_a < med_b:
                    guard_ok = False
    print(f"coverage guard (oracle rows): {'OK' if guard_ok else 'REGRESSION'}")
    print("E5 VERDICT: " + ("PASS" if (ok and guard_ok) else "FAIL"))

    # ---- E5-DIAG: coverage-guard oracle (cov / cov2) vs unguarded ----
    diag_methods = [m for m in (METHOD_CENTRAL_CRLB_COV, METHOD_CENTRAL_CRLB_COV2)
                    if m and os.path.exists(
                        os.path.join(RESULTS_DIR, f"budget_{REGIMES[0]}",
                                     f"raw_comm_limited__{m}.csv"))]
    if diag_methods:
        print("\n# E5-DIAG: coverage-guarded oracle rows vs unguarded "
              "CentralOracle-CRLB")
        print(f"{'regime':<12} {'method':<26} {'med_mb':>8} {'med_cov':>8} "
              f"{'p_mb':>8} {'p_cov':>8}")
        print("-" * 78)
        for rg in done_rgs:
            base = data[rg][METHOD_CENTRAL_CRLB]
            for m in diag_methods:
                rows = load(os.path.join(RESULTS_DIR, f"budget_{rg}"), m)
                if not rows:
                    continue
                pmb, _ = paired_stats(metric_vector(rows, PRIMARY, float("nan")),
                                      metric_vector(base, PRIMARY, float("nan")))
                pcv, _ = paired_stats(metric_vector(rows, GUARD, float("nan")),
                                      metric_vector(base, GUARD, float("nan")))
                med_mb = np.nanmedian(metric_vector(rows, PRIMARY, float("nan")))
                med_cv = np.nanmedian(metric_vector(rows, GUARD, float("nan")))
                print(f"{rg:<12} {m:<26} {med_mb:>8.4f} {med_cv:>8.1f} "
                      f"{pmb:>8.3f} {pcv:>8.3f}")
        print("# E5-DIAG verdict (locked): guarded variants are bit-identical "
              "to the unguarded oracle (cap never binds in real trajectories) "
              "-> guard does NOT decide calibration vs structure; the "
              "locality claim rests on the local-vs-global ladder.")

    # ---- E5-CORRECTED: local-frame oracle (confound removed) ----
    loc_methods = [m for m in (METHOD_CENTRAL_CRLB_LOCAL,
                               METHOD_CENTRAL_CONFIG_LOCAL)
                   if m and os.path.exists(
                       os.path.join(RESULTS_DIR, f"budget_{REGIMES[0]}",
                                    f"raw_comm_limited__{m}.csv"))]
    if loc_methods:
        print("\n# E5-CORRECTED: local-frame oracles (same bounded_bfs movement "
              "as Coverage-U, global under-set signal)")
        print(f"{'regime':<12} {'method':<26} {'med_mb':>8} {'med_cov':>8} "
              f"{'p_mb_vsCU':>10} {'p_cov_vsCU':>10}")
        print("-" * 86)
        for rg in done_rgs:
            cu = data[rg][METHOD_COVERAGE_U]
            fb = data[rg][METHOD_FRONTIER_BOUNDED]
            pmb_base, _ = paired_stats(metric_vector(cu, PRIMARY, float("nan")),
                                       metric_vector(fb, PRIMARY, float("nan")))
            for m in [METHOD_CENTRAL_CRLB] + loc_methods:
                rows = data[rg][m]
                pmb, _ = paired_stats(metric_vector(rows, PRIMARY, float("nan")),
                                      metric_vector(cu, PRIMARY, float("nan")))
                pcv, _ = paired_stats(metric_vector(rows, GUARD, float("nan")),
                                      metric_vector(cu, GUARD, float("nan")))
                med_mb = np.nanmedian(metric_vector(rows, PRIMARY, float("nan")))
                med_cv = np.nanmedian(metric_vector(rows, GUARD, float("nan")))
                print(f"{rg:<12} {m:<26} {med_mb:>8.4f} {med_cv:>8.1f} "
                      f"{pmb:>10.2e} {pcv:>10.2e}")
        print("# E5-CORRECTED verdict (PRE_REG_E5_CORRECTED.md, outcome B): "
              "with the movement frame held byte-identical, the LOCAL "
              "Coverage-U signal still beats BOTH global-signal oracles on "
              "mean_bound and coverage (p<1e-8 all regimes). The global "
              "movement frame was a real but SECONDARY confound (CRLB 0.044->"
              "0.037 A3, 0.049->0.032 A6); the dominant effect is the SIGNAL: "
              "the dense global under-set collapses coverage (43-44% vs 72%, "
              "68-69%). Locality is what matters, not signal strength.")



if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : analysis/pareto_stats.py
# AIM    : E4-PARETO statistics: lambda plateau.
# DETAILS: lambda in {0.25,0.5,1.0,2.0} vs FB: rel-red%, paired Wilcoxon + Holm, coverage guard; verdict PASS iff >=2 lambda Holm-sig in >=1 regime, no regression.
#====================================================================================================

"""
analysis/pareto_stats.py — E4-PARETO: lambda sensitivity / accuracy-coverage
Pareto frontier for Coverage-U under the fixed budget T.

Data provenance (all seed-paired, runs 0-39):
  - Frontier-Bounded (lambda = 0) and Coverage-U at lambda = 0.5:
      results/budget_{regime}/raw_comm_limited__{method}.csv   (E4 + E4-CONFIRM)
  - Coverage-U at lambda in {0.25, 1.0, 2.0}:
      results/pareto_{regime}/raw_comm_limited__Coverage-U__lam{lam}.csv

Per regime and lambda (vs FB control):
  - accuracy : med mean_bound_final @ T (lower better), rel-FB reduction %,
               paired Wilcoxon + Holm across the 4 nonzero lambdas (within
               regime).
  - guard    : med final_coverage @ T, paired Wilcoxon + Holm across lambdas
               (no significant regression allowed).
  - support  : undetermined_final @ T (lower better), descriptive.

Pre-registered verdict (E4-PARETO):
  PASS iff, in at least one of the two regimes, >= 2 of the 4 lambda values
  satisfy BOTH (rel-FB reduction of mean_bound >= 10% AND Holm-sig on
  mean_bound_final) AND none of those lambdas has a Holm-sig coverage
  regression. Secondary reading: plateau vs knife-edge of lambda = 0.5.

Usage:
  python analysis/pareto_stats.py
"""

import csv
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np
from scipy import stats

from config import (METHOD_FRONTIER_BOUNDED, METHOD_COVERAGE_U,
                    COVERAGE_U_LAMBDA)

REGIMES = ["A3_obs005", "A6_obs005"]
RESULTS_DIR = os.path.join(os.path.dirname(os.path.dirname(
    os.path.abspath(__file__))), "results")
LAMBDAS = [0.25, COVERAGE_U_LAMBDA, 1.0, 2.0]

ACC = "mean_bound_final"
COV = "final_coverage"
UND = "undetermined_final"
MIN_RED_PCT = 10.0


def sanitize(method):
    return re.sub(r"[^\w\-]", "_", method)


def load(path):
    if not os.path.exists(path):
        return None
    with open(path, "r", encoding="utf-8") as fh:
        rows = list(csv.DictReader(fh))
    rows.sort(key=lambda r: int(r.get("run", 0)))
    return rows


def vec(rows, metric):
    out = []
    for r in rows:
        v = r.get(metric)
        try:
            out.append(float(v) if v not in (None, "") else np.nan)
        except ValueError:
            out.append(np.nan)
    return np.array(out, dtype=float)


def paired_p(a, b):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    if len(a) != len(b) or len(a) == 0:
        return 1.0
    if np.all(np.abs(a - b) < 1e-12):
        return 1.0
    try:
        _, p = stats.wilcoxon(a, b, zero_method="wilcox")
    except ValueError:
        return 1.0
    return p


def holm(ps):
    n = len(ps)
    order = np.argsort(ps)
    out = [None] * n
    for rank, idx in enumerate(order):
        out[idx] = min(1.0, ps[idx] * (n - rank))
    for i in range(n - 1, 0, -1):
        out[order[i - 1]] = min(out[order[i - 1]], out[order[i]])
    return out


def load_fb_cu(rg):
    d = os.path.join(RESULTS_DIR, f"budget_{rg}")
    fb = load(os.path.join(d, f"raw_comm_limited__{sanitize(METHOD_FRONTIER_BOUNDED)}.csv"))
    cu = load(os.path.join(d, f"raw_comm_limited__{sanitize(METHOD_COVERAGE_U)}.csv"))
    return fb, cu


def load_lam(rg, lam):
    d = os.path.join(RESULTS_DIR, f"pareto_{rg}")
    return load(os.path.join(d, f"raw_comm_limited__{sanitize(METHOD_COVERAGE_U)}__lam{lam}.csv"))


def main():
    print(f"# E4-PARETO: Coverage-U lambda sensitivity under budget T "
          f"(vs Frontier-Bounded, paired, n per cell)")
    print(f"# regimes: {REGIMES}; lambdas: {LAMBDAS} "
          f"(0 = FB control); accuracy={ACC}, guard={COV}, support={UND}\n")

    all_ok = True
    for rg in REGIMES:
        fb, cu = load_fb_cu(rg)
        if fb is None or cu is None:
            print(f"WARNING {rg}: missing FB or CU(lam=0.5) in budget_*")
            all_ok = False
            continue
        n = len(fb)
        print(f"===== {rg}  (n={n} pairs) =====")

        rows = []  # (lam, med_acc, med_cov, rel_red, p_acc, p_cov, med_und)
        for lam in LAMBDAS:
            if lam == COVERAGE_U_LAMBDA:
                cu_lam = cu
            else:
                cu_lam = load_lam(rg, lam)
                if cu_lam is None:
                    print(f"WARNING {rg} lam={lam}: missing pareto_* CSV")
                    all_ok = False
                    continue
            va = vec(cu_lam, ACC)
            vb = vec(fb, ACC)
            cv_a = vec(cu_lam, COV)
            cv_b = vec(fb, COV)
            un_a = vec(cu_lam, UND)
            med_a, med_b = np.nanmedian(va), np.nanmedian(vb)
            rel = (med_b - med_a) / med_b * 100.0 if med_b > 0 else 0.0
            p_acc = paired_p(va, vb)
            p_cov = paired_p(cv_a, cv_b)
            rows.append((lam, med_a, np.nanmedian(cv_a), rel, p_acc, p_cov,
                         np.nanmedian(un_a)))
        # FB control row (lam = 0)
        rows.insert(0, (0.0, np.nanmedian(vec(fb, ACC)),
                        np.nanmedian(vec(fb, COV)), 0.0, 1.0, 1.0,
                        np.nanmedian(vec(fb, UND))))

        # Holm across the 4 nonzero-lambda tests only (lam=0 is the control).
        non_ctrl = [r for r in rows if r[0] > 0]
        acc_ps = [r[4] for r in non_ctrl]
        cov_ps = [r[5] for r in non_ctrl]
        acc_holm = holm(acc_ps)
        cov_holm = holm(cov_ps)
        holm_map = {}
        for (lam, *_r), ah, ch in zip(non_ctrl, acc_holm, cov_holm):
            holm_map[lam] = (ah, ch)

        print(f"\n  {'lam':>5} {'med_bound_FB':>13} {'med_bound_CU':>13} "
              f"{'rel-red%':>9} {'p_acc':>8} {'p_acc_holm':>10} "
              f"{'med_cov%':>9} {'p_cov_holm':>10} {'med_und':>9}")
        print("  " + "-" * 96)
        for lam, ma, mc, rel, pa, pc, mu in rows:
            ah, ch = holm_map.get(lam, (float("nan"), float("nan")))
            print(f"  {lam:>5} {rows[0][1]:>13.4f} {ma:>13.4f} {rel:>+9.1f} "
                  f"{pa:>8.4f} {ah:>10.4f} {mc:>9.1f} {ch:>10.4f} {mu:>9.4f}")

        passing = [(lam, float(rel)) for (lam, _, _, rel, _, _, _), ah in
                   zip(non_ctrl, acc_holm) if rel >= MIN_RED_PCT and ah < 0.05]
        no_regress = all(ch >= 0.05 for (_, ch) in holm_map.values())
        print(f"\n  lambdas meeting (rel-red>={MIN_RED_PCT:.0f}% AND "
              f"Holm-sig): {passing}")
        print(f"  coverage guard (no Holm-sig regression at any lam>0): "
              f"{'OK' if no_regress else 'FAIL'}")
        all_ok = all_ok and len(passing) >= 2 and no_regress

    print(f"\n# E4-PARETO verdict: >=2 passing lambdas in >=1 regime and "
          f"no coverage regression => {'PASS' if all_ok else 'FAIL'}")


if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : analysis/phase1_stats.py
# AIM    : Phase-1 statistics: Random/FB/Richness-Angular on quality metrics, paired.
# DETAILS: per-method median [IQR] + paired Wilcoxon + Holm across all tests; no verdict (comparison table).
#====================================================================================================

"""
analysis/phase1_stats.py — Phase-1 A/B statistics (Project08).

Compares the three Phase-1 methods (Random, Frontier-Bounded,
Richness-Angular) on the LOCALIZATION-quality metrics recorded by
run_phase1.py (quality_auc, time_to_quality, quality_final), using the
paired design (same env seed per run index across methods).

Protocol (locked):
  - Paired Wilcoxon (zero_method="wilcox") per (metric, pair).
  - Holm-Bonferroni across ALL tests in the run (global).
  - Delta = matched-pairs statistic m/n^2 (positive = A better).
  - Median relative gain of A over B per run (sign flipped for metrics
    where lower is better).

Usage:
  python analysis/phase1_stats.py --dir results/phase1_S1_fov5 --max-steps 4500
  python analysis/phase1_stats.py --dir results/phase1_S1prime_fov3 --max-steps 4500
"""

import argparse
import csv
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np
from scipy import stats

from config import (METHOD_RANDOM, METHOD_FRONTIER_BOUNDED,
                    METHOD_FRONTIER_RICHNESS_ANGULAR)

METHODS = [METHOD_RANDOM, METHOD_FRONTIER_BOUNDED,
           METHOD_FRONTIER_RICHNESS_ANGULAR]

HIGHER_BETTER = {
    "quality_auc": True,
    "quality_final": True,
    "time_to_quality": False,
}

# Research comparisons (A vs B). The key test is Richness-Angular vs
# Frontier-Bounded (does the localization signal beat the geometric frame?).
PAIRS = [
    (METHOD_FRONTIER_RICHNESS_ANGULAR, METHOD_FRONTIER_BOUNDED),
    (METHOD_FRONTIER_RICHNESS_ANGULAR, METHOD_RANDOM),
    (METHOD_FRONTIER_BOUNDED, METHOD_RANDOM),
]


def sanitize(method):
    return re.sub(r"[^\w\-]", "_", method)


def load(dir_path, method):
    path = os.path.join(dir_path, f"raw_comm_limited__{sanitize(method)}.csv")
    if not os.path.exists(path):
        return None
    with open(path, "r", encoding="utf-8") as fh:
        rows = list(csv.DictReader(fh))
    rows.sort(key=lambda r: int(r.get("run", 0)))
    return rows


def _num(r, key, cap=None):
    v = r.get(key)
    if v in (None, ""):
        return cap
    try:
        return float(v)
    except ValueError:
        return cap


def metric_vector(rows, metric, max_steps):
    return np.array([_num(r, metric, max_steps) for r in rows], dtype=float)


def paired_stats(a, b):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    if len(a) != len(b) or len(a) == 0:
        return float("nan"), 0.0
    d = a - b
    if np.all(np.abs(d) < 1e-12):
        return 1.0, 0.0
    try:
        _, p = stats.wilcoxon(a, b, zero_method="wilcox")
    except ValueError:
        return 1.0, 0.0
    n = len(a)
    m = 0.0
    for i in range(n):
        m += np.sum(a[i] > b) - np.sum(a[i] < b)
    return float(p), m / (n * n)


def holm_bonferroni(ps):
    n = len(ps)
    order = np.argsort(ps)
    out = [None] * n
    for rank, idx in enumerate(order):
        out[idx] = min(1.0, ps[idx] * (n - rank))
    for i in range(n - 1, 0, -1):
        out[order[i - 1]] = min(out[order[i - 1]], out[order[i]])
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dir", required=True)
    ap.add_argument("--max-steps", type=int, default=4500,
                    help="Censoring cap for time_to_quality.")
    args = ap.parse_args()

    data = {}
    missing = []
    for m in METHODS:
        rows = load(args.dir, m)
        if rows is None or not rows:
            missing.append(m)
            continue
        data[m] = rows

    if missing:
        print("WARNING missing:", ", ".join(missing))

    print(f"# Phase-1 A/B - {args.dir}")
    print(f"# runs per method: {len(next(iter(data.values()))) if data else 0}, "
          f"censoring cap = {args.max_steps}\n")

    print("# Per-method medians [IQR]\n")
    for m in METHODS:
        if m not in data:
            continue
        parts = []
        for metric in HIGHER_BETTER:
            v = metric_vector(data[m], metric, args.max_steps)
            parts.append(f"{metric}={np.median(v):.3f} "
                         f"[{np.percentile(v, 25):.3f}-"
                         f"{np.percentile(v, 75):.3f}]")
        und = np.median([_num(r, "undetermined_final", 0.0)
                         for r in data[m]])
        parts.append(f"undetermined_final={und:.4f}")
        print(f"  {m:<18} {'  '.join(parts)}")
    print()

    tests = []
    for a, b in PAIRS:
        if a not in data or b not in data:
            continue
        for metric, higher in HIGHER_BETTER.items():
            va = metric_vector(data[a], metric, args.max_steps)
            vb = metric_vector(data[b], metric, args.max_steps)
            p, d = paired_stats(va, vb)
            med_a, med_b = np.median(va), np.median(vb)
            gain = np.nanmedian((va - vb) / np.where(vb == 0, np.nan, vb))
            if not higher:
                gain = -gain
            tests.append((a, b, metric, med_a, med_b, gain * 100.0, p, d))

    ps = [t[6] for t in tests]
    corrected = holm_bonferroni(ps)

    print("# Paired Wilcoxon + Holm-Bonferroni (global)\n")
    print(f"{'A':<16} {'B':<16} {'metric':<14} {'med_A':>7} "
          f"{'med_B':>7} {'gain%':>7} {'p':>8} {'p_holm':>8} "
          f"{'delta':>7} {'sig':>5}")
    print("-" * 100)
    for (a, b, metric, med_a, med_b, gain, p, d), pc in zip(tests, corrected):
        sig = "YES" if pc < 0.05 else "no"
        print(f"{a:<16} {b:<16} {metric:<14} {med_a:>7.3f} {med_b:>7.3f} "
              f"{gain:>+7.1f} {p:>8.4f} {pc:>8.4f} {d:>+7.3f} {sig:>5}")


if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : analysis/deploy_stats.py
# AIM    : E3 statistics: Deploy-U vs FB on steps_dual, verdict.
# DETAILS: PRIMARY steps_dual censored at --max-steps; MIN_GAIN_PCT=8.0; PASS iff median gain>=8% AND any Holm-sig.
#====================================================================================================

"""
analysis/deploy_stats.py — E3 A/B statistics: Deploy-U vs Frontier-Bounded.

Compares the localization-aware deployment strategy (Deploy-U) against the
validated movement control (Frontier-Bounded) across the four E3 regimes
(A2/A3/A6 at obs=5%, A6 at obs=20%), paired by env seed (run index).

Primary (pre-registered): steps_dual = first step where BOTH coverage >= 90%
AND quality >= 0.9 (the title's "Accuracy AND Coverage"). Censored at
--max-steps.

Protocol (locked, mirrors phase1_stats):
  - Paired Wilcoxon (zero_method="wilcox") per regime on the primary metric.
  - Holm-Bonferroni across the 4 regimes (global).
  - Delta = matched-pairs statistic m/n^2 (positive = Deploy-U better).
  - Median relative gain of Deploy-U over Frontier-Bounded (sign flipped so
    positive = Deploy-U better for lower-is-better metrics).

A4 verdict: median gain >= 8% AND global Holm p < 0.05 on the primary metric.

Usage:
  python analysis/deploy_stats.py --max-steps 8000
"""

import csv
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np
from scipy import stats

from config import METHOD_FRONTIER_BOUNDED, METHOD_DEPLOY

REGIMES = ["A2_obs005", "A3_obs005", "A6_obs005", "A6_obs020"]
RESULTS_DIR = os.path.join(os.path.dirname(os.path.dirname(
    os.path.abspath(__file__))), "results")

PRIMARY = "steps_dual"
SECONDARY = ["steps_90", "quality_auc", "time_to_quality", "quality_final",
             "mean_bound_final", "deploy_frac", "orbit_frac"]
# lower-is-better metrics (positive gain = Deploy-U better when smaller)
LOWER_BETTER = {"steps_dual", "steps_90", "time_to_quality"}
MIN_GAIN_PCT = 8.0  # A4 preregistered threshold


def sanitize(method):
    return re.sub(r"[^\w\-]", "_", method)


def load(dir_path, method):
    path = os.path.join(dir_path, f"raw_comm_limited__{sanitize(method)}.csv")
    if not os.path.exists(path):
        return None
    with open(path, "r", encoding="utf-8") as fh:
        rows = list(csv.DictReader(fh))
    rows.sort(key=lambda r: int(r.get("run", 0)))
    return rows


def _num(r, key, cap=None):
    v = r.get(key)
    if v in (None, ""):
        return cap
    try:
        return float(v)
    except ValueError:
        return cap


def metric_vector(rows, metric, max_steps):
    return np.array([_num(r, metric, max_steps) for r in rows], dtype=float)


def paired_stats(a, b):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    if len(a) != len(b) or len(a) == 0:
        return float("nan"), 0.0
    d = a - b
    if np.all(np.abs(d) < 1e-12):
        return 1.0, 0.0
    try:
        _, p = stats.wilcoxon(a, b, zero_method="wilcox")
    except ValueError:
        return 1.0, 0.0
    n = len(a)
    m = 0.0
    for i in range(n):
        m += np.sum(a[i] > b) - np.sum(a[i] < b)
    return float(p), m / (n * n)


def holm_bonferroni(ps):
    n = len(ps)
    order = np.argsort(ps)
    out = [None] * n
    for rank, idx in enumerate(order):
        out[idx] = min(1.0, ps[idx] * (n - rank))
    for i in range(n - 1, 0, -1):
        out[order[i - 1]] = min(out[order[i - 1]], out[order[i]])
    return out


def main():
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument("--max-steps", type=int, default=8000,
                    help="Censoring cap for steps_dual / steps_90.")
    args = ap.parse_args()

    data = {}
    for rg in REGIMES:
        d = os.path.join(RESULTS_DIR, f"deploy_{rg}")
        fb = load(d, METHOD_FRONTIER_BOUNDED)
        du = load(d, METHOD_DEPLOY)
        if fb is None or du is None or not fb or not du:
            print(f"WARNING incomplete regime {rg}: "
                  f"FB={0 if fb is None else len(fb)} "
                  f"DU={0 if du is None else len(du)}")
            continue
        data[rg] = (fb, du)

    print(f"# E3 A/B: {METHOD_DEPLOY} vs {METHOD_FRONTIER_BOUNDED} "
          f"(paired, censored at {args.max_steps})")
    print("# PRIMARY metric: steps_dual (coverage>=90% AND quality>=0.9)\n")

    print("# Per-regime medians [IQR]\n")
    for rg in REGIMES:
        if rg not in data:
            continue
        fb, du = data[rg]
        parts = []
        for metric in [PRIMARY] + SECONDARY:
            vf = metric_vector(fb, metric, args.max_steps)
            vd = metric_vector(du, metric, args.max_steps)
            parts.append(f"{metric}="
                         f"FB {np.median(vf):.3f} / DU {np.median(vd):.3f}")
        print(f"  {rg:<12} {'  '.join(parts)}")
    print()

    # --- PRIMARY: paired Wilcoxon per regime + Holm across regimes ---
    rows = []
    for rg in REGIMES:
        if rg not in data:
            continue
        fb, du = data[rg]
        va = metric_vector(fb, PRIMARY, args.max_steps)
        vb = metric_vector(du, PRIMARY, args.max_steps)
        p, d = paired_stats(va, vb)
        med_a, med_b = np.median(va), np.median(vb)
        gain = np.nanmedian((va - vb) / np.where(va == 0, np.nan, va)) * 100.0
        rows.append((rg, med_a, med_b, gain, p, d))

    ps = [r[4] for r in rows]
    corrected = holm_bonferroni(ps)

    print("# PRIMARY paired Wilcoxon + Holm (global across regimes)\n")
    print(f"{'regime':<12} {'med_FB':>8} {'med_DU':>8} {'gain%':>7} "
          f"{'p':>8} {'p_holm':>8} {'delta':>7} {'sig':>5}")
    print("-" * 72)
    for (rg, med_a, med_b, gain, p, d), pc in zip(rows, corrected):
        sig = "YES" if pc < 0.05 else "no"
        print(f"{rg:<12} {med_a:>8.0f} {med_b:>8.0f} {gain:>+7.1f} "
              f"{p:>8.4f} {pc:>8.4f} {d:>+7.3f} {sig:>5}")

    # --- A4 verdict on the primary metric ---
    if rows:
        gains = [r[3] for r in rows]
        med_gain = float(np.median(gains))
        sig_all = [pc < 0.05 for pc in corrected]
        any_sig = any(sig_all)
        passed = med_gain >= MIN_GAIN_PCT and any_sig
        print()
        print(f"# A4 verdict (primary=steps_dual): median gain = "
              f"{med_gain:+.1f}% (threshold {MIN_GAIN_PCT:+.0f}%), "
              f"any Holm-sig = {any_sig}")
        print(f"#   => {'PASS' if passed else 'FAIL'}")

    # --- secondary metrics across regimes (informational) ---
    print("\n# Secondary metrics (medians, gain% = Deploy-U better)")
    print(f"{'metric':<18} {'regime':<12} {'med_FB':>8} {'med_DU':>8} "
          f"{'gain%':>7}")
    print("-" * 60)
    for metric in SECONDARY:
        for rg in REGIMES:
            if rg not in data:
                continue
            fb, du = data[rg]
            va = metric_vector(fb, metric, args.max_steps)
            vb = metric_vector(du, metric, args.max_steps)
            med_a, med_b = np.median(va), np.median(vb)
            denom = va if metric in LOWER_BETTER else vb
            ref = vb if metric in LOWER_BETTER else va
            gain = np.nanmedian(
                (va - vb) / np.where(denom == 0, np.nan, denom)) * 100.0
            if metric in LOWER_BETTER:
                gain = -gain
            print(f"{metric:<18} {rg:<12} {med_a:>8.3f} {med_b:>8.3f} "
                  f"{gain:>+7.1f}")


if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : analysis/pairwise_stats.py
# AIM    : V4 campaign paired comparisons (7 methods, steps_90 censored).
# DETAILS: 11 research comparisons; paired Wilcoxon + Holm across all; no verdict.
#====================================================================================================

"""
analysis/pairwise_stats.py — Paired comparisons for the V4 campaign.

Methods (all comm_limited, R=FOV, 30 paired seeds):
  Phase 1: Frontier, Least-Visited Greedy, Chao-U (bias_cap), Entropy,
           Entropy-Frac.
  Phase 2: Frontier+Entropy, Frontier+Richness.

Research comparisons:
  Entropy      vs Entropy-Frac    (count vs fractional informational signal)
  Entropy      vs Frontier
  Entropy-Frac vs Frontier
  Entropy      vs Chao-U
  Entropy-Frac vs Chao-U
  Frontier     vs Chao-U          (baseline sanity)
  Frontier+Entropy  vs Entropy-Frac   (does geometry add to pure entropy?)
  Frontier+Richness vs Frontier+Entropy (richness vs entropy, same architecture)
  Frontier+Richness vs Frontier         (does richness beat pure frontier?)
  Frontier+Richness vs Chao-U           (richness target-selection vs global gate)
  Frontier+Richness vs Entropy-Frac

Protocol: paired Wilcoxon on steps_90 (censored at MAX_STEPS) + Holm-Bonferroni
across all comparisons. Delta = matched-pairs statistic m/n^2 (positive = A
tends to finish sooner). No narrative without p-values.

Usage:
  python analysis/pairwise_stats.py [--dir results/baseline]
"""

import argparse
import csv
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np
from scipy import stats

from config import (MAX_STEPS, METHOD_FRONTIER, METHOD_GREEDY, METHOD_CHAO_U,
                    METHOD_ENTROPY, METHOD_ENTROPY_FRAC,
                    METHOD_FRONTIER_ENTROPY, METHOD_FRONTIER_RICHNESS)

METHODS = [METHOD_FRONTIER, METHOD_GREEDY, METHOD_CHAO_U,
           METHOD_ENTROPY, METHOD_ENTROPY_FRAC,
           METHOD_FRONTIER_ENTROPY, METHOD_FRONTIER_RICHNESS]

# Research comparisons (A vs B: negative delta means B is faster).
PAIRS = [
    (METHOD_ENTROPY, METHOD_ENTROPY_FRAC),
    (METHOD_ENTROPY, METHOD_FRONTIER),
    (METHOD_ENTROPY_FRAC, METHOD_FRONTIER),
    (METHOD_ENTROPY, METHOD_CHAO_U),
    (METHOD_ENTROPY_FRAC, METHOD_CHAO_U),
    (METHOD_FRONTIER, METHOD_CHAO_U),
    (METHOD_FRONTIER_ENTROPY, METHOD_ENTROPY_FRAC),
    (METHOD_FRONTIER_RICHNESS, METHOD_FRONTIER_ENTROPY),
    (METHOD_FRONTIER_RICHNESS, METHOD_FRONTIER),
    (METHOD_FRONTIER_RICHNESS, METHOD_CHAO_U),
    (METHOD_FRONTIER_RICHNESS, METHOD_ENTROPY_FRAC),
]


def sanitize(method):
    import re
    return re.sub(r"[^\w\-]", "_", method)


def file_for(out_dir, method):
    variant = "bias_cap" if method == METHOD_CHAO_U else None
    safe = sanitize(method)
    if variant is not None:
        safe = f"{safe}@{variant}"
    return os.path.join(out_dir, f"raw_comm_limited__{safe}.csv")


def load(path):
    if not os.path.exists(path):
        return None
    with open(path, "r", encoding="utf-8") as fh:
        rows = list(csv.DictReader(fh))
    rows.sort(key=lambda r: int(r.get("run", 0)))
    steps = np.array([MAX_STEPS if r["steps_90"] in (None, "")
                      else float(r["steps_90"]) for r in rows])
    cens = sum(1 for r in rows if str(r.get("censored")).lower() in ("1", "true"))
    return steps, cens


def paired_stats(a, b):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    d = a - b
    if np.all(np.abs(d) < 1e-12):
        return 1.0, 0.0
    try:
        _, p = stats.wilcoxon(a, b, zero_method="wilcox")
    except ValueError:
        return 1.0, 0.0
    n = len(a)
    m = 0.0
    for i in range(n):
        m += np.sum(a[i] > b) - np.sum(a[i] < b)
    return float(p), m / (n * n)


def holm_bonferroni(ps):
    n = len(ps)
    order = np.argsort(ps)
    out = [None] * n
    for rank, idx in enumerate(order):
        out[idx] = min(1.0, ps[idx] * (n - rank))
    for i in range(n - 1, 0, -1):
        out[order[i - 1]] = min(out[order[i - 1]], out[order[i]])
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dir", default="results/baseline")
    args = ap.parse_args()

    data = {}
    missing = []
    for m in METHODS:
        r = load(file_for(args.dir, m))
        if r is None:
            missing.append(m)
            continue
        data[m] = r

    if missing:
        print("WARNING missing:", ", ".join(missing))

    print("# V4 Phase 1 — medians/IQR of steps_90 (censored=MAX_STEPS=10000)\n")
    for m in METHODS:
        if m not in data:
            continue
        s = data[m][0]
        print(f"{m:>20} med={np.median(s):.0f} "
              f"[{np.percentile(s, 25):.0f}-{np.percentile(s, 75):.0f}] "
              f"mean={np.mean(s):.0f} cens={data[m][1]}")
    print()

    print("# Paired Wilcoxon + Holm-Bonferroni\n")
    table = []
    for a, b in PAIRS:
        if a not in data or b not in data:
            continue
        p, d = paired_stats(data[a][0], data[b][0])
        table.append((a, b, p, d))

    ps = [t[2] for t in table]
    corrected = holm_bonferroni(ps)
    print(f"{'A':<18} {'B':<18} {'p':>9} {'p_holm':>9} {'delta':>7} {'sig':>5}")
    print("-" * 70)
    for (a, b, p, d), pc in zip(table, corrected):
        sig = "YES" if pc < 0.05 else "no"
        print(f"{a:<18} {b:<18} {p:>9.4f} {pc:>9.4f} {d:>+7.3f} {sig:>5}")


if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : analysis/validate_u_gap.py
# AIM    : E1: is local config-count a reliable indicator of localization need? (live episodes).
# DETAILS: rho_count>=0.6, rho_bound<=-0.30, precision>=0.50, recall>=0.25, rho_U_gap>=0.6; appends results/validate_u_gap.csv.
#====================================================================================================

"""
analysis/validate_u_gap.py — E1: is the local richness/config-count signal a
reliable indicator of localization need in the swarm?

Question (gate for the deployment strategy): can an agent's LOCAL config-count
map (the only signal the deployment policy can use) tell it where localization
work remains?

For each regime (agents x obstacle) and 10 paired episodes (Frontier-Bounded),
sample at several steps and pool per-agent known-cell samples:

  rho_count   : Spearman(local config count, global config count) over the
                cells the agent knows -> does the local map reflect reality?
  rho_bound   : Spearman(local config count, global CRLB bound) over known
                cells -> does the local map indicate under-localization?
  precision   : among known cells with local count <= 1, fraction that are
                truly not well-localized (global bound > QUALITY_THRESHOLD)
  recall      : fraction of all truly not-well-localized cells detected
  rho_U_gap   : Spearman(agent scalar richness U_local, true gap fraction)
                over (run, step, agent) points -> does the estimator track
                the swarm's remaining localization work?

E1 verdict (pre-registered):
  local map usable if  rho_count >= 0.6, rho_bound <= -0.30,
                       precision >= 0.50, recall >= 0.25
  scalar U tracks gap if rho_U_gap >= 0.6
  (reported per regime; a regime failing these is documented, not silently kept)

Usage:
  python analysis/validate_u_gap.py [--runs 10] [--steps 4500]
"""

import argparse
import csv
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np

from env import GridEnv
from metrics import coverage_percent
from policies.factory import build_policy
from utils.seed_manager import env_seed_for_run
from estimators.richness import chao_u
from estimators.validation import spearman
from config import (METHOD_FRONTIER_BOUNDED, GRID_SIZE, DEFAULT_FOV_RADIUS,
                    QUALITY_THRESHOLD)

REGIMES = [
    {"label": "A2_obs005", "num_agents": 2, "obstacle_ratio": 0.05},
    {"label": "A3_obs005", "num_agents": 3, "obstacle_ratio": 0.05},
    {"label": "A6_obs005", "num_agents": 6, "obstacle_ratio": 0.05},
    {"label": "A6_obs020", "num_agents": 6, "obstacle_ratio": 0.20},
]

SAMPLE_STEPS = [1000, 2500, 4500]

# E1 pre-registered thresholds.
THR_RHO_COUNT = 0.6
THR_RHO_BOUND = -0.30
THR_PRECISION = 0.50
THR_RECALL = 0.25
THR_RHO_U_GAP = 0.6


def sample(env, step):
    bound = env.global_bound_grid()
    gc = env.global_config_count_grid()
    tr = ~env.obstacle_map
    gap = (bound > QUALITY_THRESHOLD) & tr
    gap_frac = float(np.sum(gap)) / (int(np.sum(tr)) or 1)
    rows = []
    for i in range(env.num_agents):
        lc = env.get_config_count_grid(i)
        seen = env.local_seen_mask[i]
        obs = env.local_obstacle_map[i]
        known = seen & ~obs
        n_known = int(np.sum(known))
        rec = {"run": None, "step": step, "agent": i, "n_known": n_known,
               "gap_frac": gap_frac}
        if n_known >= 20:
            kc = known & tr
            lcv = lc[kc].astype(np.float64)
            gcv = gc[kc].astype(np.float64)
            bv = bound[kc]
            rc, _ = spearman(lcv, gcv)
            rb, _ = spearman(lcv, bv)
            pred = known & (lc <= 1)
            hit = pred & gap
            n_pred = int(np.sum(pred))
            n_gap = int(np.sum(gap))
            rec.update({
                "rho_count": float(rc),
                "rho_bound": float(rb),
                "precision": (float(np.sum(hit)) / n_pred if n_pred else 0.0),
                "recall": (float(np.sum(hit)) / n_gap if n_gap else 0.0),
                "u_local": chao_u(lc, known, obs,
                                  total_unknown=env.get_total_undetermined(i),
                                  variant="bias_cap"),
            })
        rows.append(rec)
    return rows


def run_one(run_index, num_agents, obstacle_ratio, steps, fov_radius,
            sample_steps):
    env_seed = env_seed_for_run(run_index)
    env = GridEnv(grid_size=GRID_SIZE, num_agents=num_agents,
                  obstacle_ratio=obstacle_ratio, seed=env_seed,
                  info_model="comm_limited")
    env.quality_threshold = QUALITY_THRESHOLD

    policies = [
        build_policy(METHOD_FRONTIER_BOUNDED, seed=env_seed * 1000 + i + 1,
                     fov_radius=fov_radius, horizon=8)
        for i in range(num_agents)
    ]

    t0 = time.perf_counter()
    samples = []
    done_steps = 0
    for step in range(1, steps + 1):
        env.check_and_merge()
        actions = [policies[i].select_action(env, i)[0]
                   for i in range(num_agents)]
        env.step(actions)
        done_steps = step
        if step in sample_steps:
            samples.extend(sample(env, step))
        if coverage_percent(env) >= 100.0:
            break
    if done_steps not in sample_steps and samples:
        pass
    wall = time.perf_counter() - t0
    return env, samples, done_steps, wall


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--runs", type=int, default=10)
    ap.add_argument("--steps", type=int, default=4500)
    ap.add_argument("--fov", type=int, default=DEFAULT_FOV_RADIUS)
    ap.add_argument("--out", default="results/validate_u_gap.csv")
    args = ap.parse_args()

    os.makedirs(os.path.dirname(args.out) or ".", exist_ok=True)
    fieldnames = ["regime", "run", "step", "agent", "n_known", "gap_frac",
                  "rho_count", "rho_bound", "precision", "recall", "u_local"]
    new_file = not os.path.exists(args.out)
    done = set()
    if not new_file:
        with open(args.out, "r", encoding="utf-8") as f:
            for row in csv.DictReader(f):
                done.add((row["regime"], int(row["run"])))
    fh = open(args.out, "a", newline="", encoding="utf-8")
    writer = csv.DictWriter(fh, fieldnames=fieldnames)
    if new_file:
        writer.writeheader()

    print("# E1 - local config-count signal vs true localization gap\n")
    summary = []
    for rg in REGIMES:
        label = rg["label"]
        print(f"=== {label}  agents={rg['num_agents']} "
              f"obstacle={rg['obstacle_ratio']} ===", flush=True)
        rows = []
        for run in range(args.runs):
            if (label, run) in done:
                continue
            env, samples, nsteps, wall = run_one(
                run, rg["num_agents"], rg["obstacle_ratio"], args.steps,
                args.fov, SAMPLE_STEPS)
            for s in samples:
                row = {"regime": label, **s}
                row["run"] = run
                writer.writerow({k: ("" if row[k] is None else round(float(row[k]), 6))
                                 if k not in ("regime", "run", "step", "agent")
                                 else row[k] for k in fieldnames})
            fh.flush()
            rows.extend(samples)
            print(f"    run {run + 1}/{args.runs}: steps={nsteps} "
                  f"in {wall:.0f}s", flush=True)

        if not rows:
            with open(args.out, "r", encoding="utf-8") as f:
                for row in csv.DictReader(f):
                    if row["regime"] == label:
                        rows.append(row)
            for r in rows:
                for k in ("rho_count", "rho_bound", "precision", "recall",
                          "u_local", "gap_frac"):
                    r[k] = float(r[k]) if r[k] not in ("",) else float("nan")
                r["n_known"] = int(r["n_known"])

        valid = [r for r in rows if r["rho_count"] == r["rho_count"]]
        if not valid:
            continue
        lc = np.array([r["u_local"] for r in valid], dtype=float)
        gf = np.array([r["gap_frac"] for r in valid], dtype=float)
        rho_ug, p_ug = spearman(lc, gf)
        rho_c = np.mean([r["rho_count"] for r in valid])
        rho_b = np.mean([r["rho_bound"] for r in valid])
        prec = np.mean([r["precision"] for r in valid])
        rec = np.mean([r["recall"] for r in valid])
        med_gap = np.median([r["gap_frac"] for r in valid])
        print(f"  gap_frac med={med_gap:.4f}")
        print(f"  rho_count (local vs global counts, mean over samples) = "
              f"{rho_c:.3f}")
        print(f"  rho_bound (local count vs bound, mean)                = "
              f"{rho_b:.3f}")
        print(f"  precision={prec:.3f}  recall={rec:.3f}")
        print(f"  rho(U_local, gap_frac) pooled = {rho_ug:.3f} (p={p_ug:.2e})")
        print()
        summary.append({
            "regime": label, "gap_frac": med_gap,
            "rho_count": rho_c, "rho_bound": rho_b,
            "precision": prec, "recall": rec,
            "rho_U_gap": rho_ug, "rho_U_gap_p": p_ug,
        })

    fh.close()
    print("# E1 summary")
    print(f"{'regime':<12} {'gap':>6} {'rho_count':>9} {'rho_bound':>9} "
          f"{'prec':>5} {'rec':>5} {'rho_Ugap':>8}")
    print("-" * 60)
    for s in summary:
        print(f"{s['regime']:<12} {s['gap_frac']:>6.4f} {s['rho_count']:>9.3f} "
              f"{s['rho_bound']:>9.3f} {s['precision']:>5.2f} "
              f"{s['recall']:>5.2f} {s['rho_U_gap']:>8.3f}")
    print(f"\nSaved -> {args.out}")


if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : analysis/headroom_check.py
# AIM    : Step-0 diagnostic: does FB leave localization work (f1_frac) at episode end?
# DETAILS: records coverage, quality_final, f0/f1/f2plus/cap_hit fractions; results/headroom_variants.csv.
#====================================================================================================

"""
analysis/headroom_check.py — Step-0 diagnostic for the richness re-observation
controller (Project08).

Question: is there a regime where Frontier-Bounded leaves localization work on
the table at the end of an episode? If yes, the re-observation controller has
headroom to exploit. If no (F1 -> 0 everywhere), the premise fails.

Measures per (agents, obstacle_ratio) variant, over NUM_RUNS paired episodes:
  coverage      : final coverage %
  quality_final : fraction of traversable cells well-localized (CRLB <= 1.5)
  f0_frac       : traversable cells with 0 global configurations (unseen)
  f1_frac       : traversable cells with exactly 1 configuration (SEEN but not
                  localizable -> the headroom the controller would target)
  f2plus_frac   : traversable cells with >= 2 configurations
  cap_hit_frac  : cluster-cap saturation on the local decision signal

Usage:
  python analysis/headroom_check.py [--runs 10] [--steps 4500]
"""

import argparse
import csv
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np

from env import GridEnv
from metrics import coverage_percent
from policies.factory import build_policy
from utils.seed_manager import env_seed_for_run
from config import (METHOD_FRONTIER_BOUNDED, GRID_SIZE, DEFAULT_FOV_RADIUS,
                    DEFAULT_OBSTACLE_RATIO, QUALITY_THRESHOLD)

VARIANT_DEFS = [
    {"label": "A2_obs005", "num_agents": 2, "obstacle_ratio": 0.05},
    {"label": "A3_obs005", "num_agents": 3, "obstacle_ratio": 0.05},
    {"label": "A6_obs020", "num_agents": 6, "obstacle_ratio": 0.20},
]


def run_one(run_index, num_agents, obstacle_ratio, steps, fov_radius):
    env_seed = env_seed_for_run(run_index)
    env = GridEnv(grid_size=GRID_SIZE, num_agents=num_agents,
                  obstacle_ratio=obstacle_ratio, seed=env_seed,
                  info_model="comm_limited")
    env.quality_threshold = QUALITY_THRESHOLD

    policies = [
        build_policy(METHOD_FRONTIER_BOUNDED, seed=env_seed * 1000 + i + 1,
                     fov_radius=fov_radius, horizon=8)
        for i in range(num_agents)
    ]

    t0 = time.perf_counter()
    for _ in range(steps):
        env.check_and_merge()
        actions = [policies[i].select_action(env, i)[0]
                   for i in range(num_agents)]
        env.step(actions)
        if coverage_percent(env) >= 100.0:
            break
    wall = time.perf_counter() - t0

    counts = env.global_config_count_grid()
    tr = ~env.obstacle_map
    n_trav = int(tr.sum()) or 1
    f0 = int(np.sum((counts == 0) & tr)) / n_trav
    f1 = int(np.sum((counts == 1) & tr)) / n_trav
    f2p = int(np.sum((counts >= 2) & tr)) / n_trav

    return {
        "coverage": coverage_percent(env),
        "quality_final": env.quality_well_localized(),
        "f0_frac": f0,
        "f1_frac": f1,
        "f2plus_frac": f2p,
        "cap_hit_frac": env.cluster_cap_hit_frac(),
        "wall_time_s": wall,
    }


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--runs", type=int, default=10)
    ap.add_argument("--steps", type=int, default=4500)
    ap.add_argument("--fov", type=int, default=DEFAULT_FOV_RADIUS)
    ap.add_argument("--out", default="results/headroom_variants.csv")
    args = ap.parse_args()

    os.makedirs(os.path.dirname(args.out) or ".", exist_ok=True)
    fieldnames = ["variant", "num_agents", "obstacle_ratio", "run",
                  "coverage", "quality_final", "f0_frac", "f1_frac",
                  "f2plus_frac", "cap_hit_frac", "wall_time_s"]
    new_file = not os.path.exists(args.out)
    done = set()
    if not new_file:
        with open(args.out, "r", encoding="utf-8") as f:
            for row in csv.DictReader(f):
                done.add((row["variant"], int(row["run"])))
    fh = open(args.out, "a", newline="", encoding="utf-8")
    writer = csv.DictWriter(fh, fieldnames=fieldnames)
    if new_file:
        writer.writeheader()

    for vd in VARIANT_DEFS:
        print(f"=== {vd['label']}  agents={vd['num_agents']} "
              f"obstacle={vd['obstacle_ratio']} ===", flush=True)
        rows = []
        for run in range(args.runs):
            if (vd["label"], run) in done:
                continue
            r = run_one(run, vd["num_agents"], vd["obstacle_ratio"],
                        args.steps, args.fov)
            row = {"variant": vd["label"], "num_agents": vd["num_agents"],
                   "obstacle_ratio": vd["obstacle_ratio"], "run": run, **r}
            out_row = dict(row)
            for k in ("coverage", "quality_final", "f0_frac", "f1_frac",
                      "f2plus_frac", "cap_hit_frac", "wall_time_s"):
                v = row[k]
                out_row[k] = "" if v is None else round(float(v), 6)
            writer.writerow(out_row)
            fh.flush()
            rows.append(r)
            print(f"    run {run + 1}/{args.runs}: cov={r['coverage']:.1f} "
                  f"q={r['quality_final']:.3f} f1={r['f1_frac']:.3f} "
                  f"in {r['wall_time_s']:.0f}s", flush=True)
        if rows:
            print(f"  MEAN over {args.runs}: cov={np.mean([r['coverage'] for r in rows]):.1f} "
                  f"quality_final={np.mean([r['quality_final'] for r in rows]):.3f} "
                  f"f1={np.mean([r['f1_frac'] for r in rows]):.3f} "
                  f"f0={np.mean([r['f0_frac'] for r in rows]):.3f} "
                  f"f2plus={np.mean([r['f2plus_frac'] for r in rows]):.3f}", flush=True)
        else:
            print(f"  (all runs already in {args.out}, skipped)", flush=True)
    fh.close()
    print(f"\nSaved -> {args.out}")


if __name__ == "__main__":
    main()


#====================================================================================================
# FILE   : analysis/compute_entropy.py
# AIM    : Vectorized per-cell signal maps for V4 policies (local knowledge bundle only).
# DETAILS: p_map, H_map, info_gain_count_map, info_gain_frac_map, richness_map, frontier_mask, select_target; brute-force scalar reference for tests.
#====================================================================================================

"""
analysis/compute_entropy.py — Vectorized per-cell signal maps for V4 policies.

All functions operate on the agent's local knowledge bundle {visit, known, obs}
(no global truth), consistent with the comm_limited info model.

Signal conventions (locked):
  - Probability map p: unknown cell  -> 0.5; known free -> P_known;
    known obstacle -> 1 - P_known. Deterministic, no environmental noise.
  - H(p) = binary entropy in bits (H(0.5)=1, H(0.9)=H(0.1)~0.469).
  - info_gain (count) = number of UNKNOWN cells in the window.
  - info_gain (frac)  = sum of H over the window.
  - richness          = Chao-U bias_cap evaluated on the window.
  - frontier_mask     = known free cells with >= 1 unknown 4-neighbor.
"""

import numpy as np

from estimators.richness import chao_u
from policies._common import box_sum

LOG2 = np.log(2.0)


def p_map(known, obs, p_known=0.9):
    """Deterministic probability map under the sensor-reliability model."""
    p = np.full(known.shape, 0.5, dtype=np.float64)
    known_free = known & ~obs
    known_obs = known & obs
    p[known_free] = p_known
    p[known_obs] = 1.0 - p_known
    return p


def H_map(p):
    """Binary entropy in bits, vectorized; H(0)=H(1)=0."""
    p = np.clip(p, 1e-12, 1.0 - 1e-12)
    return -(p * np.log(p) + (1.0 - p) * np.log1p(-p)) / LOG2


def info_gain_count_map(unknown, w):
    """Per-cell count of unknown cells in the radius-w window (count signal)."""
    return box_sum(unknown, w)


def info_gain_frac_map(known, obs, w, p_known=0.9):
    """Per-cell sum of H(p) over the radius-w window (fractional signal)."""
    return box_sum(H_map(p_map(known, obs, p_known)), w)


def richness_map(visit, known, obs, w, total_unknown):
    """Per-cell Chao-U bias_cap on the radius-w window.

    For every cell c: F1(c) = # traversable cells with visit==1 inside the
    window, F2(c) = # with visit==2. U_bias = F1(F1-1)/(2(F2+1)) is then
    capped at `total_unknown` and floored at 1, matching richness.chao_u
    with variant="bias_cap" evaluated window-wise.
    """
    traversable = known & ~obs
    ones = traversable & (visit == 1)
    twos = traversable & (visit == 2)
    F1 = box_sum(ones.astype(np.float64), w)
    F2 = box_sum(twos.astype(np.float64), w)
    U = (F1 * (F1 - 1.0)) / (2.0 * (F2 + 1.0))
    U = np.minimum(U, float(max(int(total_unknown), 0)))
    return np.maximum(U, 1.0)


def frontier_mask(known, obs, unknown):
    """Known free cells adjacent (4-neighborhood) to >= 1 unknown cell."""
    unknown = np.asarray(unknown, dtype=bool)
    gs = known.shape[0]
    adj = np.zeros_like(unknown)
    adj[:-1, :] |= unknown[1:, :]
    adj[1:, :] |= unknown[:-1, :]
    adj[:, :-1] |= unknown[:, 1:]
    adj[:, 1:] |= unknown[:, :-1]
    return (known & ~obs & adj).astype(np.float64)


def select_target(utility, D, curdir, candidate_mask, rng, tie_eps=1e-3):
    """Pick the argmax utility cell among candidates with D>0 (within the BFS
    horizon), tie-broken by a small per-agent scatter. Returns the first-step
    action (int) or None if no candidate is reachable within the horizon."""
    reachable = (np.asarray(candidate_mask, dtype=bool)) & (D > 0)
    if not reachable.any():
        return None
    vals = utility[reachable].copy()
    if tie_eps > 0:
        vals = vals + rng.uniform(-tie_eps, tie_eps, size=vals.shape)
    j = int(np.argmax(vals))
    idx = np.argwhere(reachable)[j]
    tr, tc = int(idx[0]), int(idx[1])
    return int(curdir[tr, tc])


def window_radius(default, configured):
    """Resolve ENTROPY_WINDOW: None -> default (FOV radius)."""
    return default if configured is None else configured


def _window_chao_u_scalar_sanity(visit, known, obs, w, total_unknown):
    """Reference scalar implementation (tests only): brute-force window loop,
    equivalent to richness_map but O(N^2) — used to validate the vectorized
    version."""
    gs = visit.shape[0]
    out = np.zeros((gs, gs), dtype=np.float64)
    for r in range(gs):
        for c in range(gs):
            r0, r1 = max(0, r - w), min(gs, r + w + 1)
            c0, c1 = max(0, c - w), min(gs, c + w + 1)
            sub_visit = visit[r0:r1, c0:c1]
            sub_known = known[r0:r1, c0:c1]
            sub_obs = obs[r0:r1, c0:c1]
            out[r, c] = chao_u(sub_visit, sub_known, sub_obs,
                               total_unknown=total_unknown, variant="bias_cap")
    return out


