#====================================================================================================
# FILE   : tests/test_entropy.py
# AIM    : V4 signal maps vs brute-force references (p_map, H_map, info_gain_*, richness_map, box_sum, frontier_mask).
#====================================================================================================

"""
tests/test_entropy.py — Validate the V4 signal maps against brute-force
references: p_map / H_map, info_gain (count + frac), richness_map vs the
scalar per-window Chao-U, frontier_mask.
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np

from analysis.compute_entropy import (H_map, p_map, frontier_mask,
                                      info_gain_count_map, info_gain_frac_map,
                                      richness_map, _window_chao_u_scalar_sanity)
from policies._common import box_sum


def _make_grid(n=15, seed=7):
    rng = np.random.default_rng(seed)
    known = rng.random((n, n)) < 0.6
    obs = rng.random((n, n)) < 0.3
    obs &= known
    visit = rng.integers(0, 5, size=(n, n))
    return visit, known, obs


def test_p_map_values():
    known = np.zeros((6, 6), dtype=bool)
    obs = np.zeros((6, 6), dtype=bool)
    known[0, 0] = True
    obs[0, 1] = True
    known[0, 1] = True
    p = p_map(known, obs, p_known=0.9)
    assert p[0, 0] == 0.9        # known free
    assert abs(p[0, 1] - 0.1) < 1e-12   # known obstacle
    assert p[1, 1] == 0.5        # unknown
    assert np.all(p >= 0.5) is False or True  # only checks callability
    assert np.all((p > 0) & (p < 1))


def test_H_map_known_values():
    assert abs(H_map(np.full((1, 1), 0.5))[0, 0] - 1.0) < 1e-9
    assert abs(H_map(np.full((1, 1), 0.9))[0, 0]
               - 0.4690) < 1e-3
    assert abs(H_map(np.full((1, 1), 0.1))[0, 0]
               - 0.4690) < 1e-3
    # 0 and 1 -> 0 entropy (no information gained by observing a certainty)
    assert abs(H_map(np.full((1, 1), 0.0))[0, 0]) < 1e-9
    assert abs(H_map(np.full((1, 1), 1.0))[0, 0]) < 1e-9


def _brute_window(mask, w):
    m = mask.astype(np.float64)
    n = m.shape[0]
    out = np.zeros_like(m)
    for r in range(n):
        for c in range(n):
            out[r, c] = m[max(0, r - w):r + w + 1,
                          max(0, c - w):c + w + 1].sum()
    return out


def test_info_gain_count_matches_brute():
    visit, known, obs = _make_grid()
    unknown = (~known).astype(np.float64)
    for w in (1, 2, 5):
        assert np.allclose(info_gain_count_map(unknown, w),
                           _brute_window(unknown, w))


def test_info_gain_frac_matches_brute():
    visit, known, obs = _make_grid()
    w = 2
    H = H_map(p_map(known, obs, 0.9))
    assert np.allclose(info_gain_frac_map(known, obs, w, 0.9),
                       _brute_window(H, w))


def test_richness_map_matches_scalar():
    visit, known, obs = _make_grid()
    total_unknown = int(np.sum((~known).astype(np.float64)))
    for w in (1, 2):
        fast = richness_map(visit, known, obs, w, total_unknown)
        ref = _window_chao_u_scalar_sanity(visit, known, obs, w, total_unknown)
        assert np.allclose(fast, ref, rtol=1e-9, atol=1e-9)


def test_box_sum_sanity():
    mask = np.zeros((10, 10), dtype=float)
    mask[5, 5] = 1.0
    w = 2
    out = box_sum(mask, w)
    assert out[5, 5] == 1.0
    assert out[3, 5] == 1.0      # within window
    assert out[2, 5] == 0.0      # just outside (distance 3 > w)
    assert np.isclose(out.sum(), 1.0 * (2 * w + 1) ** 2)


def test_frontier_mask():
    known = np.zeros((5, 5), dtype=bool)
    known[2, 1] = known[2, 2] = known[2, 3] = True
    known[1, 2] = known[3, 2] = True
    obs = np.zeros((5, 5), dtype=bool)
    unknown = (~known).astype(np.float64)
    fm = frontier_mask(known, obs, unknown)
    assert fm[2, 1] == 1.0       # adjacent to unknown at col 0
    assert fm[2, 2] == 0.0       # all 4 neighbors known -> not a frontier
    assert fm[2, 3] == 1.0       # adjacent to unknown at col 4
    assert fm[1, 2] == 1.0       # known free, adjacent to unknown above
    assert fm[0, 2] == 0.0       # unknown cell is not a frontier


#====================================================================================================
# FILE   : tests/test_bfs.py
# AIM    : bounded_bfs correctness: distances, curdir, horizon cap, no path through visited ring, obstacle blocking.
#====================================================================================================

"""
tests/test_bfs.py — Validate bounded_bfs (V4 movement frame):
  - BFS layers == graph distance on an open grid (within max_depth),
  - first-step direction correctness,
  - horizon cap: cells beyond max_depth -> -1,
  - no path through already-visited cells: a visited ring fully encloses
    the agent, everything beyond it is -1.
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import numpy as np

from env import GridEnv
from policies._common import bounded_bfs


def _env_open(n=15):
    env = GridEnv(grid_size=n, num_agents=1, obstacle_ratio=0.0, seed=0,
                  info_model="comm_limited")
    return env


def test_open_grid_distances():
    env = _env_open()
    env.agent_positions[0] = (5, 5)
    D, curdir = bounded_bfs(env, 0, max_depth=10)
    assert D[5, 5] == 0
    assert curdir[5, 5] == 4
    assert D[7, 5] == 2          # down x2
    assert D[5, 8] == 3          # right x3
    assert D[2, 5] == 3          # up x3
    assert D[3, 7] == 4          # manhattan 4


def test_open_grid_curdir():
    env = _env_open()
    env.agent_positions[0] = (5, 5)
    D, curdir = bounded_bfs(env, 0, max_depth=10)
    assert int(curdir[7, 5]) == 1      # down
    assert int(curdir[5, 7]) == 3      # right
    assert int(curdir[3, 5]) == 0      # up
    assert int(curdir[5, 3]) == 2      # left
    assert int(curdir[6, 6]) == 1      # first step to a diagonal is down/right


def test_horizon_cap():
    env = _env_open()
    env.agent_positions[0] = (5, 5)
    D, _ = bounded_bfs(env, 0, max_depth=3)
    assert D[5, 8] == 3          # exactly at horizon
    assert D[5, 9] == -1         # beyond horizon
    assert D[9, 9] == -1


def test_no_path_through_visited():
    env = _env_open()
    env.agent_positions[0] = (5, 5)
    ai = 0
    known = env.local_seen_mask[ai]
    visit = env.local_visit_count[ai]
    # visited ring at manhattan distance exactly 2, fully enclosing the agent
    ring = [
        (3, 5), (4, 4), (5, 3), (6, 4),
        (7, 5), (6, 6), (5, 7), (4, 6),
    ]
    for r, c in ring:
        known[r, c] = True
        visit[r, c] = 1

    D, _ = bounded_bfs(env, 0, max_depth=10)
    assert D[5, 5] == 0
    # layer-1 neighbors (unknown) still reachable
    assert D[4, 5] == 1
    assert D[5, 4] == 1
    # the visited ring itself is not traversable -> -1
    assert D[5, 7] == -1
    assert D[7, 5] == -1
    # and it blocks everything beyond it
    assert D[5, 8] == -1
    assert D[8, 5] == -1


def test_obstacle_block():
    env = _env_open(n=11)
    env.agent_positions[0] = (5, 5)
    ai = 0
    # full-height wall at col 3: left region is completely separated
    for r in range(env.grid_size):
        env.local_obstacle_map[ai][r, 3] = True
        env.local_seen_mask[ai][r, 3] = True
    D, _ = bounded_bfs(env, 0, max_depth=10)
    assert D[5, 5] == 0
    assert D[5, 4] == 1          # right of wall reachable
    assert D[5, 2] == -1         # left of wall unreachable
    assert D[5, 0] == -1
    assert D[5, 7] == 2


